import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Movie {
  id: string;
  title: string;
  description: string;
  thumbnail: string;
  heroImage?: string;
  year: string;
  rating: string;
  duration: string;
  category: string;
  tags: string[];
}

export enum Category {
  POPULAR = 'Popular on Netflix',
  TRENDING = 'Trending Now',
  ORIGINALS = 'Netflix Originals',
  WATCH_AGAIN = 'Watch It Again',
  AWARD_WINNING = 'Award-Winning TV Shows'
}

import React, { useState, useEffect } from 'react';
import { Search, Bell, Menu, User, X } from 'lucide-react';

const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 0);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed top-0 w-full z-50 transition-all duration-300 px-6 lg:px-12 py-4 flex items-center justify-between ${isScrolled ? 'bg-black/90 backdrop-blur-md border-b border-white/10' : 'bg-transparent'}`}>
      <div className="flex items-center gap-10">
        <h1 className="text-3xl font-extrabold text-[#E50914] tracking-tighter cursor-pointer">NETFLIX</h1>

        <ul className="hidden md:flex items-center gap-6 text-sm font-medium text-gray-300">
          <li className="hover:text-white cursor-pointer transition-colors text-white font-semibold">Home</li>
          <li className="hover:text-white cursor-pointer transition-colors">TV Shows</li>
          <li className="hover:text-white cursor-pointer transition-colors">Movies</li>
          <li className="hover:text-white cursor-pointer transition-colors">New & Popular</li>
          <li className="hover:text-white cursor-pointer transition-colors">My List</li>
        </ul>
      </div>

      <div className="flex items-center gap-6">
        <div className="relative group hidden sm:block">
          <Search className="w-5 h-5 text-gray-300 group-hover:text-white cursor-pointer transition-colors" />
        </div>
        <Bell className="w-5 h-5 text-gray-300 hover:text-white cursor-pointer transition-colors hidden sm:block" />

        <div className="flex items-center gap-2 group cursor-pointer">
          <div className="w-8 h-8 rounded-md bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center text-xs font-bold shadow-lg group-hover:ring-2 group-hover:ring-white transition-all">
            JD
          </div>
          <span className="text-sm font-medium hidden lg:block">John Doe</span>
        </div>

        <button 
          className="md:hidden"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X /> : <Menu />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="absolute top-full left-0 w-full bg-black/95 border-b border-white/10 p-6 flex flex-col gap-4 md:hidden">
          <a href="#" className="text-lg font-medium">Home</a>
          <a href="#" className="text-lg font-medium text-gray-400">TV Shows</a>
          <a href="#" className="text-lg font-medium text-gray-400">Movies</a>
          <a href="#" className="text-lg font-medium text-gray-400">New & Popular</a>
          <a href="#" className="text-lg font-medium text-gray-400">My List</a>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

