import React, { useRef } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { Movie } from '../types';
import MovieCard from './MovieCard';

interface MovieRowProps {
  title: string;
  movies: Movie[];
  onPlay: (movie: Movie) => void;
}

const MovieRow: React.FC<MovieRowProps> = ({ title, movies, onPlay }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  const scroll = (direction: 'left' | 'right') => {
    if (scrollRef.current) {
      const { scrollLeft, clientWidth } = scrollRef.current;
      const scrollTo = direction === 'left' ? scrollLeft - clientWidth : scrollLeft + clientWidth;
      scrollRef.current.scrollTo({ left: scrollTo, behavior: 'smooth' });
    }
  };

  return (
    <div className="relative mb-12 group/row">
      <h3 className="text-xl md:text-2xl font-bold mb-4 px-6 lg:px-12 group-hover:text-red-500 transition-colors">
        {title}
      </h3>

      <div className="relative">
        <button 
          onClick={() => scroll('left')}
          className="absolute left-0 top-0 bottom-0 z-40 bg-black/50 hover:bg-black/70 px-2 opacity-0 group-hover/row:opacity-100 transition-opacity"
        >
          <ChevronLeft className="w-10 h-10" />
        </button>

        <div 
          ref={scrollRef}
          className="flex gap-4 overflow-x-auto no-scrollbar px-6 lg:px-12 pb-10"
        >
          {movies.map(movie => (
            <MovieCard key={movie.id} movie={movie} onPlay={onPlay} />
          ))}
        </div>

        <button 
          onClick={() => scroll('right')}
          className="absolute right-0 top-0 bottom-0 z-40 bg-black/50 hover:bg-black/70 px-2 opacity-0 group-hover/row:opacity-100 transition-opacity"
        >
          <ChevronRight className="w-10 h-10" />
        </button>
      </div>
    </div>
  );
};

export default MovieRow;

import React, { useState, useEffect } from 'react';
import { Play, Pause, SkipBack, SkipForward, Volume2, VolumeX, Maximize, X, Settings } from 'lucide-react';
import { Movie } from '../types';

interface VideoPlayerProps {
  movie: Movie;
  onClose: () => void;
}

const VideoPlayer: React.FC<VideoPlayerProps> = ({ movie, onClose }) => {
  const [isPlaying, setIsPlaying] = useState(true);
  const [isMuted, setIsMuted] = useState(false);
  const [progress, setProgress] = useState(0);
  const [showControls, setShowControls] = useState(true);

  useEffect(() => {
    let timeout: NodeJS.Timeout;
    const handleMouseMove = () => {
      setShowControls(true);
      clearTimeout(timeout);
      timeout = setTimeout(() => setShowControls(false), 3000);
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      clearTimeout(timeout);
    };
  }, []);

  return (
    <div className="fixed inset-0 z-[100] bg-black flex items-center justify-center">
      {/* Pseudo-video Background */}
      <div 
        className="absolute inset-0 bg-cover bg-center opacity-40 blur-sm"
        style={{ backgroundImage: `url(${movie.heroImage || movie.thumbnail})` }}
      />

      <div className="relative w-full h-full flex flex-col justify-between">
        {/* Header */}
        <div className={`p-8 flex items-center justify-between transition-opacity duration-500 ${showControls ? 'opacity-100' : 'opacity-0'}`}>
          <div className="flex flex-col">
            <span className="text-red-600 font-bold tracking-widest text-sm uppercase">Playing Now</span>
            <h2 className="text-3xl font-black">{movie.title}</h2>
          </div>
          <button 
            onClick={onClose}
            className="p-3 bg-white/10 rounded-full hover:bg-white/20 transition-all border border-white/20"
          >
            <X className="w-8 h-8" />
          </button>
        </div>

        {/* Center Playback Animation Simulation */}
        <div className="flex-1 flex items-center justify-center">
            {isPlaying ? (
              <div className="animate-pulse flex flex-col items-center">
                 <div className="w-32 h-32 rounded-full border-4 border-red-600 flex items-center justify-center">
                   <Play fill="white" className="w-12 h-12 ml-2" />
                 </div>
                 <p className="mt-8 text-xl font-medium tracking-widest text-white/50">STREAMING HIGH DEFINITION</p>
              </div>
            ) : (
                <Pause className="w-24 h-24 text-white/50" />
            )}
        </div>

        {/* Controls Panel */}
        <div className={`p-8 glass-panel m-8 rounded-2xl transition-all duration-500 transform ${showControls ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-12'}`}>
          {/* Progress Bar */}
          <div className="relative w-full h-1 bg-white/20 rounded-full mb-6 cursor-pointer group">
            <div 
              className="absolute h-full bg-red-600 rounded-full transition-all"
              style={{ width: `${progress}%` }}
            />
            <div className="absolute top-1/2 -translate-y-1/2 w-4 h-4 bg-red-600 rounded-full scale-0 group-hover:scale-100 transition-transform" style={{ left: `${progress}%` }} />
          </div>

          <div className="flex items-center justify-between">
            <div className="flex items-center gap-8">
              <button onClick={() => setIsPlaying(!isPlaying)} className="hover:text-red-500 transition-colors">
                {isPlaying ? <Pause className="w-8 h-8" /> : <Play fill="currentColor" className="w-8 h-8" />}
              </button>
              <SkipBack className="w-6 h-6 hover:text-red-500 transition-colors cursor-pointer" />
              <SkipForward className="w-6 h-6 hover:text-red-500 transition-colors cursor-pointer" />
              <div className="flex items-center gap-4 ml-4">
                <button onClick={() => setIsMuted(!isMuted)}>
                  {isMuted ? <VolumeX className="w-6 h-6" /> : <Volume2 className="w-6 h-6" />}
                </button>
                <div className="w-24 h-1 bg-white/20 rounded-full">
                  <div className="w-2/3 h-full bg-white rounded-full" />
                </div>
              </div>
            </div>

            <div className="flex items-center gap-6">
              <span className="text-sm font-mono tracking-tighter">00:45:22 / {movie.duration}</span>
              <Settings className="w-6 h-6 hover:text-red-500 transition-colors cursor-pointer" />
              <Maximize className="w-6 h-6 hover:text-red-500 transition-colors cursor-pointer" />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default VideoPlayer;

import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import MovieRow from './components/MovieRow';
import VideoPlayer from './components/VideoPlayer';
import Footer from './components/Footer';
import { MOVIES } from './constants';
import { Movie, Category } from './types';

const App: React.FC = () => {
  const [selectedMovie, setSelectedMovie] = useState<Movie | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  const heroMovie = MOVIES[0]; // Money Heist
  const featuredMovie = MOVIES[1]; // Skyscraper

  const getMoviesByCategory = (category: string) => {
    return MOVIES.filter(m => m.category === category || m.id === '3' || m.id === '4');
  };

  const handlePlay = (movie: Movie) => {
    setSelectedMovie(movie);
    setIsPlaying(true);
  };

  return (
    <div className="bg-black min-h-screen text-white overflow-hidden">
      <Navbar />

      <main className="relative pb-20">
        <Hero 
          movie={heroMovie} 
          onPlay={handlePlay} 
        />

        {/* Content Rows */}
        <div className="relative -mt-32 z-10 space-y-8">
          <MovieRow 
            title={Category.ORIGINALS} 
            movies={MOVIES.filter(m => m.category === Category.ORIGINALS)} 
            onPlay={handlePlay}
          />

          <MovieRow 
            title={Category.TRENDING} 
            movies={MOVIES.filter(m => m.category === Category.TRENDING || m.category === Category.POPULAR)} 
            onPlay={handlePlay}
          />

          {/* Special Featured Section */}
          <div className="px-6 lg:px-12 my-20">
            <div className="relative h-[60vh] rounded-3xl overflow-hidden glass-panel group">
              <div 
                className="absolute inset-0 bg-cover bg-center transition-transform duration-1000 group-hover:scale-105"
                style={{ backgroundImage: `url(${featuredMovie.heroImage || featuredMovie.thumbnail})` }}
              />
              <div className="absolute inset-0 bg-gradient-to-r from-black via-black/40 to-transparent p-12 flex flex-col justify-center max-w-2xl">
                <span className="text-red-500 font-bold tracking-[0.3em] text-xs mb-4 uppercase">Featured Spotlight</span>
                <h2 className="text-5xl font-black mb-6 uppercase tracking-tight">{featuredMovie.title}</h2>
                <p className="text-lg text-gray-300 mb-8 leading-relaxed line-clamp-2">
                  {featuredMovie.description}
                </p>
                <div className="flex gap-4">
                  <button 
                    onClick={() => handlePlay(featuredMovie)}
                    className="bg-red-600 hover:bg-red-700 text-white px-8 py-3 rounded-full font-bold transition-all transform hover:scale-105 active:scale-95 shadow-xl shadow-red-600/20"
                  >
                    Watch Now
                  </button>
                  <button className="bg-white/10 backdrop-blur-md hover:bg-white/20 text-white px-8 py-3 rounded-full font-bold transition-all border border-white/10">
                    Add to List
                  </button>
                </div>
              </div>
            </div>
          </div>

          <MovieRow 
            title={Category.AWARD_WINNING} 
            movies={MOVIES.slice().reverse()} 
            onPlay={handlePlay}
          />

          <MovieRow 
            title={Category.POPULAR} 
            movies={MOVIES} 
            onPlay={handlePlay}
          />
        </div>
      </main>

      <Footer />

      {/* Video Player Modal */}
      {isPlaying && selectedMovie && (
        <VideoPlayer 
          movie={selectedMovie} 
          onClose={() => setIsPlaying(false)} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
