            <X className="w-8 h-8" />
          </button>
        </div>

        {/* Center Playback Animation Simulation */}
        <div className="flex-1 flex items-center justify-center">
            {isPlaying ? (
              <div className="animate-pulse flex flex-col items-center">
                 <div className="w-32 h-32 rounded-full border-4 border-red-600 flex items-center justify-center">
                   <Play fill="white" className="w-12 h-12 ml-2" />
                 </div>
                 <p className="mt-8 text-xl font-medium tracking-widest text-white/50">STREAMING HIGH DEFINITION</p>
              </div>
            ) : (
                <Pause className="w-24 h-24 text-white/50" />
            )}
