        {/* Controls Panel */}
        <div className={`p-8 glass-panel m-8 rounded-2xl transition-all duration-500 transform ${showControls ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-12'}`}>
          {/* Progress Bar */}
