  netflixOriginals: `${TMDB_BASE_URL}/discover/tv?api_key=${TMDB_API_KEY}&with_networks=213`,
  topRated: `${TMDB_BASE_URL}/movie/top_rated?api_key=${TMDB_API_KEY}&language=en-US`,
  actionMovies: `${TMDB_BASE_URL}/discover/movie?api_key=${TMDB_API_KEY}&with_genres=28`,
  comedyMovies: `${TMDB_BASE_URL}/discover/movie?api_key=${TMDB_API_KEY}&with_genres=35`,
