};

import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import MovieRow from './components/MovieRow';
import VideoPlayer from './components/VideoPlayer';
import Footer from './components/Footer';
import { FETCH_URLS, TMDB_IMAGE_BASE_URL, FALLBACK_MOVIE } from './constants';
import { Movie, Category } from './types';

const App: React.FC = () => {
  const [selectedMovie, setSelectedMovie] = useState<Movie | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [moviesData, setMoviesData] = useState<{ [key: string]: Movie[] }>({});
  const [loading, setLoading] = useState(true);

  const mapTMDBToMovie = (item: any, category: string): Movie => {
    return {
      id: item.id.toString(),
      title: item.title || item.name || item.original_name || 'Untitled',
      description: item.overview || 'No description available.',
      thumbnail: item.poster_path ? `${TMDB_IMAGE_BASE_URL}/w500${item.poster_path}` : FALLBACK_MOVIE.thumbnail,
      heroImage: item.backdrop_path ? `${TMDB_IMAGE_BASE_URL}/original${item.backdrop_path}` : FALLBACK_MOVIE.heroImage,
      year: (item.release_date || item.first_air_date || '').split('-')[0] || '2024',
      rating: item.vote_average ? item.vote_average.toFixed(1) : 'NR',
      duration: item.media_type === 'tv' ? 'Series' : 'Movie',
      category: category,
      tags: ['Trending', 'Hot'] // Placeholder for genres
    };
  };

  useEffect(() => {
    const fetchAllData = async () => {
      try {
        const fetchRequests = Object.entries(FETCH_URLS).map(async ([key, url]) => {
          const response = await fetch(url);
          const data = await response.json();
          return {
            key,
            movies: data.results.map((item: any) => mapTMDBToMovie(item, key))
          };
        });

        const results = await Promise.all(fetchRequests);
        const newData: { [key: string]: Movie[] } = {};
        results.forEach(res => {
          newData[res.key] = res.movies;
        });
        setMoviesData(newData);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching TMDB data:', error);
        setLoading(false);
      }
    };

    fetchAllData();
  }, []);

  const handlePlay = (movie: Movie) => {
    setSelectedMovie(movie);
    setIsPlaying(true);
  };

  // Select Hero Movie: Use the first trending item or fallback
  const heroMovie = moviesData.trending?.[0] || FALLBACK_MOVIE;
  // Select Spotlight Movie: Use the first action movie or fallback
  const featuredMovie = moviesData.actionMovies?.[0] || FALLBACK_MOVIE;

  if (loading) {
    return (
      <div className="bg-black min-h-screen flex items-center justify-center">
        <div className="flex flex-col items-center gap-6">
          <h1 className="text-5xl font-black text-[#E50914] animate-pulse">NETFLIX</h1>
          <div className="w-48 h-1 bg-neutral-800 rounded-full overflow-hidden">
            <div className="h-full bg-red-600 animate-[loading_2s_ease-in-out_infinite]" style={{ width: '40%' }}></div>
          </div>
        </div>
        <style>{`
          @keyframes loading {
            0% { transform: translateX(-100%); }
            100% { transform: translateX(250%); }
          }
        `}</style>
      </div>
    );
  }

  return (
    <div className="bg-black min-h-screen text-white overflow-hidden">
      <Navbar />

      <main className="relative pb-20">
        <Hero 
          movie={heroMovie} 
          onPlay={handlePlay} 
        />

        {/* Content Rows */}
        <div className="relative -mt-32 z-10 space-y-8">
          {moviesData.netflixOriginals && (
            <MovieRow 
              title={Category.ORIGINALS} 
              movies={moviesData.netflixOriginals} 
              onPlay={handlePlay}
            />
          )}

          {moviesData.trending && (
            <MovieRow 
              title={Category.TRENDING} 
              movies={moviesData.trending} 
              onPlay={handlePlay}
            />
          )}

          {/* Special Featured Section */}
          <div className="px-6 lg:px-12 my-20">
            <div className="relative h-[60vh] rounded-3xl overflow-hidden glass-panel group">
              <div 
                className="absolute inset-0 bg-cover bg-center transition-transform duration-1000 group-hover:scale-105"
                style={{ backgroundImage: `url(${featuredMovie.heroImage})` }}
              />
              <div className="absolute inset-0 bg-gradient-to-r from-black via-black/40 to-transparent p-12 flex flex-col justify-center max-w-2xl">
                <span className="text-red-500 font-bold tracking-[0.3em] text-xs mb-4 uppercase">Featured Spotlight</span>
                <h2 className="text-4xl md:text-5xl font-black mb-6 uppercase tracking-tight leading-tight">
                  {featuredMovie.title}
                </h2>
                <p className="text-lg text-gray-300 mb-8 leading-relaxed line-clamp-3">
                  {featuredMovie.description}
                </p>
                <div className="flex gap-4">
                  <button 
                    onClick={() => handlePlay(featuredMovie)}
                    className="bg-red-600 hover:bg-red-700 text-white px-8 py-3 rounded-full font-bold transition-all transform hover:scale-105 active:scale-95 shadow-xl shadow-red-600/20"
                  >
                    Watch Now
                  </button>
                  <button className="bg-white/10 backdrop-blur-md hover:bg-white/20 text-white px-8 py-3 rounded-full font-bold transition-all border border-white/10">
                    Add to List
                  </button>
                </div>
              </div>
            </div>
          </div>

          {moviesData.topRated && (
            <MovieRow 
              title={Category.TOP_RATED} 
              movies={moviesData.topRated} 
              onPlay={handlePlay}
            />
          )}

          {moviesData.comedyMovies && (
            <MovieRow 
              title={Category.COMEDY} 
              movies={moviesData.comedyMovies} 
              onPlay={handlePlay}
            />
          )}

          {moviesData.documentaries && (
            <MovieRow 
              title="Documentaries" 
              movies={moviesData.documentaries} 
              onPlay={handlePlay}
            />
          )}
        </div>
      </main>

      <Footer />

      {/* Video Player Modal */}
      {isPlaying && selectedMovie && (
        <VideoPlayer 
          movie={selectedMovie} 
          onClose={() => setIsPlaying(false)} 
        />
      )}
    </div>
  );
};

export default App;

