import React, { useRef } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { Movie } from '../types';
import MovieCard from './MovieCard';

interface MovieRowProps {
  title: string;
  movies: Movie[];
  onPlay: (movie: Movie) => void;
}

const MovieRow: React.FC<MovieRowProps> = ({ title, movies, onPlay }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  const scroll = (direction: 'left' | 'right') => {
    if (scrollRef.current) {
      const { scrollLeft, clientWidth } = scrollRef.current;
      const scrollTo = direction === 'left' ? scrollLeft - clientWidth : scrollLeft + clientWidth;
      scrollRef.current.scrollTo({ left: scrollTo, behavior: 'smooth' });
    }
  };

  return (
    <div className="relative mb-16 group/row">
      <div className="flex items-center justify-between mb-6 px-6 lg:px-12">
        <h3 className="text-2xl font-black uppercase tracking-tighter group-hover:text-blue-500 transition-colors italic">
          {title}
        </h3>
        <button className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500 hover:text-white transition-colors">
          View All Database
        </button>
      </div>

      <div className="relative">
        <button 
          onClick={() => scroll('left')}
          className="absolute left-0 top-0 bottom-0 z-40 bg-gradient-to-r from-black/80 to-transparent hover:from-black px-4 opacity-0 group-hover/row:opacity-100 transition-opacity"
        >
          <ChevronLeft className="w-10 h-10 text-white" />
        </button>

        <div 
          ref={scrollRef}
          className="flex gap-6 overflow-x-auto no-scrollbar px-6 lg:px-12 pb-10"
        >
          {movies.map(movie => (
            <MovieCard key={movie.id} movie={movie} onPlay={onPlay} />
          ))}
        </div>

        <button 
          onClick={() => scroll('right')}
          className="absolute right-0 top-0 bottom-0 z-40 bg-gradient-to-l from-black/80 to-transparent hover:from-black px-4 opacity-0 group-hover/row:opacity-100 transition-opacity"
        >
          <ChevronRight className="w-10 h-10 text-white" />
        </button>
      </div>
    </div>
  );
};

export default MovieRow;

