                </div>
                <h2 className="text-5xl md:text-7xl font-black mb-8 uppercase tracking-tighter leading-none italic">
                  {featuredMovie.title}
                </h2>
                <p className="text-xl text-gray-300 mb-10 leading-relaxed line-clamp-3 font-medium drop-shadow-lg">
