              </div>
          </div>
          <button 
            onClick={onClose}
            className="p-4 bg-white/10 rounded-full hover:bg-white/20 transition-all border border-white/20 shadow-2xl backdrop-blur-xl group"
          >
            <X className="w-6 h-6 group-hover:rotate-90 transition-transform duration-300" />
          </button>
        </div>

        {/* Center Playback Animation Simulation */}
        <div className="flex-1 flex items-center justify-center">
            {isPlaying ? (
              <div className="animate-pulse flex flex-col items-center">
                 <div className="w-32 h-32 rounded-full border-4 border-blue-600/50 flex items-center justify-center shadow-[0_0_50px_rgba(59,130,246,0.3)]">
