                   </div>
                 </div>
                 <p className="mt-10 text-xs font-black tracking-[0.6em] text-blue-500 uppercase">Master Grade Stream</p>
              </div>
            ) : (
                <div className="p-12 rounded-full bg-white/5 border border-white/10 backdrop-blur-xl">
                    <Pause className="w-16 h-16 text-white" />
                </div>
            )}
        </div>

        {/* Controls Panel */}
        <div className={`p-8 glass-panel m-12 rounded-[2rem] transition-all duration-500 transform ${showControls ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-12'}`}>
          {/* Progress Bar */}
          <div className="relative w-full h-1.5 bg-white/10 rounded-full mb-8 cursor-pointer group">
            <div 
              className="absolute h-full bg-blue-600 rounded-full transition-all shadow-[0_0_15px_rgba(59,130,246,0.8)]"
              style={{ width: `${progress + 35}%` }}
            />
            <div className="absolute top-1/2 -translate-y-1/2 w-4 h-4 bg-blue-500 rounded-full scale-0 group-hover:scale-100 transition-transform shadow-lg border-2 border-white" style={{ left: `${progress + 35}%` }} />
          </div>

          <div className="flex items-center justify-between">
