              <div className="flex items-center gap-6">
                <SkipBack className="w-6 h-6 hover:text-blue-500 transition-colors cursor-pointer" />
                <SkipForward className="w-6 h-6 hover:text-blue-500 transition-colors cursor-pointer" />
              </div>
              <div className="flex items-center gap-4 ml-6">
                <button onClick={() => setIsMuted(!isMuted)} className="hover:text-blue-500 transition-colors">
                  {isMuted ? <VolumeX className="w-6 h-6" /> : <Volume2 className="w-6 h-6" />}
