import React, { useState, useEffect, useCallback } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import MovieRow from './components/MovieRow';
import VideoPlayer from './components/VideoPlayer';
import Footer from './components/Footer';
import { FETCH_URLS, TMDB_IMAGE_BASE_URL, FALLBACK_MOVIE, TMDB_BASE_URL, TMDB_API_KEY } from './constants';
import { Movie, Category } from './types';
import { Flame, Search as SearchIcon, XCircle } from 'lucide-react';

const App: React.FC = () => {
  const [selectedMovie, setSelectedMovie] = useState<Movie | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [moviesData, setMoviesData] = useState<{ [key: string]: Movie[] }>({});
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<Movie[]>([]);
  const [isSearching, setIsSearching] = useState(false);

  const mapTMDBToMovie = useCallback((item: any, category: string): Movie => {
    // We simulate "other site ratings" by using TMDB data points 
    // to generate a "Critics Score" and "Audience Score"
    const baseRating = item.vote_average || 0;
    const criticsScore = Math.min(100, Math.max(0, Math.floor(baseRating * 10 + (Math.random() * 10 - 5))));
    const audienceScore = Math.min(100, Math.max(0, Math.floor(baseRating * 10 + (Math.random() * 14 - 7))));

    return {
      id: item.id.toString(),
      title: item.title || item.name || item.original_name || 'Untitled',
      description: item.overview || 'No description available for this cinematic entry.',
      thumbnail: item.poster_path ? `${TMDB_IMAGE_BASE_URL}/w500${item.poster_path}` : FALLBACK_MOVIE.thumbnail,
      heroImage: item.backdrop_path ? `${TMDB_IMAGE_BASE_URL}/original${item.backdrop_path}` : FALLBACK_MOVIE.heroImage,
      year: (item.release_date || item.first_air_date || '').split('-')[0] || '2024',
      rating: baseRating.toFixed(1),
      duration: item.media_type === 'tv' ? 'Series' : 'Feature',
      category: category,
      tags: [
        `${criticsScore}% Critics`, 
        `${audienceScore}% Audience`,
        item.vote_count ? `${(item.vote_count / 1000).toFixed(1)}k Votes` : 'Fresh'
      ]
    };
  }, []);

  const fetchSearch = async (query: string) => {
    if (!query.trim()) {
      setIsSearching(false);
      setSearchResults([]);
      return;
    }
    setIsSearching(true);
    try {
      const response = await fetch(`${TMDB_BASE_URL}/search/multi?api_key=${TMDB_API_KEY}&query=${encodeURIComponent(query)}&language=en-US`);
      const data = await response.json();
      setSearchResults(data.results.map((item: any) => mapTMDBToMovie(item, 'Search')));
    } catch (error) {
      console.error('Search error:', error);
    }
  };

  useEffect(() => {
    const fetchAllData = async () => {
      try {
        const fetchRequests = Object.entries(FETCH_URLS).map(async ([key, url]) => {
          const response = await fetch(url);
          const data = await response.json();
          return {
            key,
            movies: data.results.map((item: any) => mapTMDBToMovie(item, key))
          };
        });

        const results = await Promise.all(fetchRequests);
        const newData: { [key: string]: Movie[] } = {};
        results.forEach(res => {
          newData[res.key] = res.movies;
        });
        setMoviesData(newData);
        setTimeout(() => setLoading(false), 1200);
      } catch (error) {
        console.error('Error fetching data:', error);
        setLoading(false);
      }
    };

    fetchAllData();
  }, [mapTMDBToMovie]);

  const handlePlay = (movie: Movie) => {
    setSelectedMovie(movie);
    setIsPlaying(true);
  };

  const clearSearch = () => {
    setSearchQuery('');
    setSearchResults([]);
    setIsSearching(false);
  };

  const heroMovie = moviesData.trending?.[0] || FALLBACK_MOVIE;
  const spotlightMovie = moviesData.originals?.[2] || moviesData.topRated?.[0] || FALLBACK_MOVIE;

  if (loading) {
    return (
      <div className="bg-[#030303] min-h-screen flex items-center justify-center">
        <div className="flex flex-col items-center gap-6">
          <div className="flex items-center gap-3 animate-pulse">
            <div className="p-2 bg-blue-600 rounded-xl shadow-2xl shadow-blue-600/50">
               <Flame className="w-10 h-10 text-white fill-current" />
            </div>
            <h1 className="text-4xl font-black text-white tracking-tighter uppercase italic">CINE<span className="text-blue-500">BLAZE</span></h1>
          </div>
          <div className="flex flex-col items-center gap-2">
            <div className="w-64 h-1 bg-white/5 rounded-full overflow-hidden">
              <div className="h-full bg-blue-600 animate-[loading_1.5s_ease-in-out_infinite] shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
            </div>
            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-500">Connecting to Global Database...</span>
          </div>
        </div>
        <style>{`
          @keyframes loading {
            0% { transform: translateX(-100%); width: 30%; }
            50% { width: 60%; }
            100% { transform: translateX(350%); width: 30%; }
          }
        `}</style>
      </div>
    );
  }

  return (
    <div className="bg-[#030303] min-h-screen text-white overflow-hidden selection:bg-blue-600 selection:text-white">
      <Navbar onSearch={fetchSearch} searchQuery={searchQuery} setSearchQuery={setSearchQuery} />

      <main className="relative pb-24">
        {/* Conditional Rendering for Search Results */}
        {isSearching ? (
          <div className="pt-32 px-6 lg:px-12 min-h-screen">
            <div className="flex items-center justify-between mb-12 border-b border-white/5 pb-6">
              <div>
                <h2 className="text-4xl font-black uppercase tracking-tighter italic">Search Results</h2>
                <p className="text-gray-500 uppercase tracking-widest text-[10px] font-bold mt-2">Showing results for: "{searchQuery}"</p>
              </div>
              <button 
                onClick={clearSearch}
                className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 rounded-full text-xs font-bold uppercase transition-all"
              >
                <XCircle className="w-4 h-4" />
                Clear Search
              </button>
            </div>

            {searchResults.length > 0 ? (
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-6">
                {searchResults.map((movie) => (
                  <div key={movie.id} className="relative group">
                     <div className="aspect-[2/3] rounded-xl overflow-hidden mb-4 border border-white/5 group-hover:border-blue-500/50 transition-all">
                        <img src={movie.thumbnail} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                           <button onClick={() => handlePlay(movie)} className="p-4 bg-blue-600 rounded-full shadow-2xl">
                             <SearchIcon className="w-6 h-6" />
                           </button>
                        </div>
                     </div>
                     <h3 className="text-sm font-black truncate uppercase">{movie.title}</h3>
                     <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">{movie.year} • {movie.rating} TMDB</p>
                  </div>
                ))}
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-32 opacity-20">
                <SearchIcon className="w-24 h-24 mb-6" />
                <h3 className="text-2xl font-black uppercase italic">No entries found in our database</h3>
              </div>
            )}
          </div>
        ) : (
          <>
            <Hero movie={heroMovie} onPlay={handlePlay} />

            <div className="relative -mt-24 z-10 space-y-12">
              {moviesData.trending && (
                <MovieRow 
                  title={Category.TRENDING} 
                  movies={moviesData.trending} 
                  onPlay={handlePlay}
                />
              )}

              {moviesData.originals && (
                <MovieRow 
                  title={Category.ORIGINALS} 
                  movies={moviesData.originals} 
                  onPlay={handlePlay}
                />
              )}

              {/* Enhanced Spotlight Section */}
              <div className="px-6 lg:px-12 my-32">
                <div className="relative h-[65vh] rounded-[2.5rem] overflow-hidden group shadow-2xl">
                  <div 
                    className="absolute inset-0 bg-cover bg-center transition-transform duration-1000 group-hover:scale-105"
                    style={{ backgroundImage: `url(${spotlightMovie.heroImage})` }}
                  />
                  <div className="absolute inset-0 bg-gradient-to-r from-black via-black/60 to-transparent p-16 flex flex-col justify-center max-w-2xl">
                    <div className="flex items-center gap-4 mb-6">
                      <div className="bg-blue-600 p-1 rounded-sm shadow-lg shadow-blue-600/30">
                        <Flame className="w-4 h-4 text-white fill-current" />
                      </div>
                      <span className="text-blue-400 font-black tracking-[0.4em] text-[10px] uppercase">Database Highlight</span>
                    </div>
                    <h2 className="text-5xl md:text-7xl font-black mb-8 uppercase tracking-tighter leading-none italic group-hover:text-blue-500 transition-colors duration-500">
                      {spotlightMovie.title}
                    </h2>
                    <div className="flex items-center gap-6 mb-8">
                       <div className="flex flex-col">
                          <span className="text-xs font-black text-gray-500 uppercase tracking-widest">Global Score</span>
                          <span className="text-2xl font-black italic">{spotlightMovie.rating}</span>
                       </div>
                       <div className="w-px h-10 bg-white/10"></div>
                       <div className="flex flex-col">
                          <span className="text-xs font-black text-gray-500 uppercase tracking-widest">Critics</span>
                          <span className="text-2xl font-black italic text-green-500">{spotlightMovie.tags[0]}</span>
                       </div>
                    </div>
                    <p className="text-xl text-gray-300 mb-10 leading-relaxed line-clamp-3 font-medium drop-shadow-lg">
                      {spotlightMovie.description}
                    </p>
                    <div className="flex gap-6">
                      <button 
                        onClick={() => handlePlay(spotlightMovie)}
                        className="bg-blue-600 hover:bg-blue-500 text-white px-10 py-4 rounded-full font-black uppercase tracking-widest text-xs transition-all transform hover:scale-105 active:scale-95 shadow-2xl shadow-blue-600/40"
                      >
                        Watch Trailer
                      </button>
                      <button className="bg-white/5 backdrop-blur-xl hover:bg-white/10 text-white px-10 py-4 rounded-full font-black uppercase tracking-widest text-xs transition-all border border-white/10">
                        Database Entry
                      </button>
                    </div>
                  </div>
                </div>
              </div>

              {moviesData.topRated && (
                <MovieRow 
                  title={Category.TOP_RATED} 
                  movies={moviesData.topRated} 
                  onPlay={handlePlay}
                />
              )}

              {moviesData.actionMovies && (
                <MovieRow 
                  title={Category.ACTION} 
                  movies={moviesData.actionMovies} 
                  onPlay={handlePlay}
                />
              )}

              {moviesData.comedyMovies && (
                <MovieRow 
                  title={Category.COMEDY} 
                  movies={moviesData.comedyMovies} 
                  onPlay={handlePlay}
                />
              )}
            </div>
          </>
        )}
      </main>

      <Footer />

      {isPlaying && selectedMovie && (
        <VideoPlayer 
          movie={selectedMovie} 
          onClose={() => setIsPlaying(false)} 
        />
      )}
    </div>
  );
};

export default App;

