          <li className="hover:text-blue-500 cursor-pointer transition-colors">Movies</li>
          <li className="hover:text-blue-500 cursor-pointer transition-colors">TV Series</li>
          <li className="hover:text-blue-500 cursor-pointer transition-colors text-gray-700 pointer-events-none">People</li>
          <li className="hover:text-blue-500 cursor-pointer transition-colors text-gray-700 pointer-events-none">Awards</li>
        </ul>
      </div>

      <div className="flex items-center gap-6">
        <form onSubmit={handleSearchSubmit} className={`relative transition-all duration-500 ${isSearchActive ? 'w-64 md:w-96' : 'w-40 md:w-56'}`}>
          <div className={`flex items-center border rounded-full px-4 py-2 transition-all ${isSearchActive ? 'bg-white/10 border-blue-500/50' : 'bg-white/5 border-white/10 hover:bg-white/10'}`}>
            <Search className={`w-4 h-4 transition-colors ${isSearchActive ? 'text-blue-500' : 'text-gray-400'}`} />
            <input 
              type="text"
              placeholder="Search database..."
              value={searchQuery}
              onFocus={() => setIsSearchActive(true)}
              onBlur={() => !searchQuery && setIsSearchActive(false)}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                if (e.target.value.length > 2) onSearch(e.target.value);
                if (e.target.value.length === 0) onSearch('');
              }}
              className="bg-transparent border-none outline-none text-xs text-white placeholder:text-gray-500 ml-3 w-full font-bold tracking-tight"
            />
            {searchQuery && (
              <button type="button" onClick={() => { setSearchQuery(''); onSearch(''); }}>
                <X className="w-3 h-3 text-gray-500 hover:text-white" />
              </button>
            )}
          </div>
        </form>

        <Bell className="w-5 h-5 text-gray-400 hover:text-blue-500 cursor-pointer transition-colors hidden sm:block" />

        <div className="flex items-center gap-2 group cursor-pointer active:scale-95 transition-transform">
          <div className="w-9 h-9 rounded-full bg-gradient-to-tr from-blue-700 to-blue-500 flex items-center justify-center text-[10px] font-black shadow-lg shadow-blue-900/40 group-hover:ring-2 group-hover:ring-blue-400 transition-all">
            JD
          </div>
        </div>

        <button 
          className="md:hidden p-2 hover:bg-white/5 rounded-full transition-colors"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="absolute top-full left-0 w-full bg-black/98 border-b border-white/5 p-8 flex flex-col gap-6 md:hidden shadow-2xl backdrop-blur-3xl animate-in slide-in-from-top duration-300">
          <button onClick={() => { setIsMobileMenuOpen(false); handleLogoClick(); }} className="text-xl font-black uppercase italic text-left hover:text-blue-500">Home</button>
          <a href="#" className="text-xl font-black uppercase italic text-gray-400">Movies</a>
          <a href="#" className="text-xl font-black uppercase italic text-gray-400">TV Shows</a>
          <a href="#" className="text-xl font-black uppercase italic text-gray-400">Award List</a>
          <div className="pt-6 border-t border-white/5 flex gap-6">
            <Bell className="w-6 h-6 text-gray-500" />
            <Search className="w-6 h-6 text-gray-500" />
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

