  return (
    <nav className={`fixed top-0 w-full z-[80] transition-all duration-300 px-6 lg:px-12 py-4 flex items-center justify-between ${isScrolled || isSearchActive ? 'bg-black/95 backdrop-blur-xl border-b border-white/5' : 'bg-transparent'}`}>
      <div className="flex items-center gap-10">
        <div onClick={handleLogoClick} className="flex items-center gap-2 group cursor-pointer active:scale-95 transition-transform">
          <div className="p-1.5 bg-blue-600 rounded-lg group-hover:bg-blue-500 transition-colors shadow-lg shadow-blue-600/20">
            <Flame className="w-6 h-6 text-white fill-current" />
          </div>
          <h1 className="text-2xl font-black text-white tracking-tighter uppercase italic">CINE<span className="text-blue-500">BLAZE</span></h1>
        </div>

        <ul className="hidden md:flex items-center gap-6 text-xs font-black uppercase tracking-widest text-gray-500">
          <li onClick={handleLogoClick} className="hover:text-blue-500 cursor-pointer transition-colors text-white">Home</li>
          <li className="hover:text-blue-500 cursor-pointer transition-colors">Movies</li>
          <li className="hover:text-blue-500 cursor-pointer transition-colors">TV Series</li>
          <li className="hover:text-blue-500 cursor-pointer transition-colors text-gray-700 pointer-events-none">People</li>
          <li className="hover:text-blue-500 cursor-pointer transition-colors text-gray-700 pointer-events-none">Awards</li>
        </ul>
      </div>

      <div className="flex items-center gap-6">
        <form onSubmit={handleSearchSubmit} className={`relative transition-all duration-500 ${isSearchActive ? 'w-64 md:w-96' : 'w-40 md:w-56'}`}>
          <div className={`flex items-center border rounded-full px-4 py-2 transition-all ${isSearchActive ? 'bg-white/10 border-blue-500/50' : 'bg-white/5 border-white/10 hover:bg-white/10'}`}>
            <Search className={`w-4 h-4 transition-colors ${isSearchActive ? 'text-blue-500' : 'text-gray-400'}`} />
            <input 
              type="text"
              placeholder="Search database..."
              value={searchQuery}
              onFocus={() => setIsSearchActive(true)}
              onBlur={() => !searchQuery && setIsSearchActive(false)}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                if (e.target.value.length > 2) onSearch(e.target.value);
                if (e.target.value.length === 0) onSearch('');
              }}
              className="bg-transparent border-none outline-none text-xs text-white placeholder:text-gray-500 ml-3 w-full font-bold tracking-tight"
            />
            {searchQuery && (
              <button type="button" onClick={() => { setSearchQuery(''); onSearch(''); }}>
                <X className="w-3 h-3 text-gray-500 hover:text-white" />
              </button>
            )}
          </div>
        </form>

        <Bell className="w-5 h-5 text-gray-400 hover:text-blue-500 cursor-pointer transition-colors hidden sm:block" />

        <div className="flex items-center gap-2 group cursor-pointer active:scale-95 transition-transform">
          <div className="w-9 h-9 rounded-full bg-gradient-to-tr from-blue-700 to-blue-500 flex items-center justify-center text-[10px] font-black shadow-lg shadow-blue-900/40 group-hover:ring-2 group-hover:ring-blue-400 transition-all">
            JD
          </div>
        </div>

        <button 
          className="md:hidden p-2 hover:bg-white/5 rounded-full transition-colors"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="absolute top-full left-0 w-full bg-black/98 border-b border-white/5 p-8 flex flex-col gap-6 md:hidden shadow-2xl backdrop-blur-3xl animate-in slide-in-from-top duration-300">
          <button onClick={() => { setIsMobileMenuOpen(false); handleLogoClick(); }} className="text-xl font-black uppercase italic text-left hover:text-blue-500">Home</button>
          <a href="#" className="text-xl font-black uppercase italic text-gray-400">Movies</a>
          <a href="#" className="text-xl font-black uppercase italic text-gray-400">TV Shows</a>
          <a href="#" className="text-xl font-black uppercase italic text-gray-400">Award List</a>
          <div className="pt-6 border-t border-white/5 flex gap-6">
            <Bell className="w-6 h-6 text-gray-500" />
            <Search className="w-6 h-6 text-gray-500" />
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, Play, Star, Plus, Share2, Award, Calendar, Clock, Globe, BrainCircuit, Users, Wallet, TrendingUp } from 'lucide-react';
import { Movie } from '../types';
import { TMDB_BASE_URL, TMDB_API_KEY, TMDB_IMAGE_BASE_URL } from '../constants';
import { GoogleGenAI } from "@google/genai";

interface DetailsPageProps {
  movie: Movie;
  onBack: () => void;
  onPlay: (movie: Movie) => void;
}

interface CastMember {
  id: number;
  name: string;
  character: string;
  profile_path: string | null;
}

interface MovieDetailsExtended {
  director: string;
  producers: string[];
  budget: number;
  revenue: number;
  runtime: number;
  cast: CastMember[];
  status: string;
}

const DetailsPage: React.FC<DetailsPageProps> = ({ movie, onBack, onPlay }) => {
  const [details, setDetails] = useState<MovieDetailsExtended | null>(null);
  const [aiVerdict, setAiVerdict] = useState<string>('');
  const [loadingAi, setLoadingAi] = useState(false);

  useEffect(() => {
    const fetchFullDetails = async () => {
      try {
        // Fetch movie details and credits in parallel
        const type = movie.duration === 'Series' ? 'tv' : 'movie';
        const [detailRes, creditRes] = await Promise.all([
          fetch(`${TMDB_BASE_URL}/${type}/${movie.id}?api_key=${TMDB_API_KEY}&language=en-US`),
          fetch(`${TMDB_BASE_URL}/${type}/${movie.id}/credits?api_key=${TMDB_API_KEY}&language=en-US`)
        ]);

        const detailData = await detailRes.json();
        const creditData = await creditRes.json();

        const director = creditData.crew?.find((c: any) => c.job === 'Director' || c.job === 'Executive Producer')?.name || 'Unknown';
        const producers = creditData.crew?.filter((c: any) => c.job === 'Producer').slice(0, 2).map((p: any) => p.name) || [];

        setDetails({
          director,
          producers,
          budget: detailData.budget || 0,
          revenue: detailData.revenue || 0,
          runtime: detailData.runtime || (detailData.episode_run_time ? detailData.episode_run_time[0] : 0),
          cast: creditData.cast?.slice(0, 10) || [],
          status: detailData.status || 'Released'
        });

        // Get AI Verdict from Gemini
        getAiVerdict(movie.title, movie.description);
      } catch (error) {
        console.error("Error fetching extended details:", error);
      }
    };

    fetchFullDetails();
  }, [movie]);

  const getAiVerdict = async (title: string, overview: string) => {
    setLoadingAi(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `As a world-class movie database critic for CineBlaze, give a punchy, 2-sentence 'Verdict' for the film "${title}". Focus on why people love it or what makes it unique based on this overview: ${overview}. Keep it bold and cinematic.`,
      });
      setAiVerdict(response.text || "Database analysis complete. Cinematic excellence confirmed.");
    } catch (e) {
      setAiVerdict("The CineBlaze AI suggests this entry is a must-watch for fans of high-quality storytelling.");
    } finally {
      setLoadingAi(false);
    }
  };

  const formatCurrency = (val: number) => {
    if (val === 0) return 'Undisclosed';
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);
  };

  return (
    <div className="min-h-screen bg-[#030303] animate-in fade-in duration-700">
      <div className="relative h-[60vh] md:h-[75vh] w-full overflow-hidden">
        <div 
          className="absolute inset-0 bg-cover bg-center transition-transform duration-1000 scale-105"
          style={{ backgroundImage: `url(${movie.heroImage || movie.thumbnail})` }}
        />
        <div className="absolute inset-0 bg-gradient-to-t from-[#030303] via-transparent to-black/40" />
        <div className="absolute inset-0 bg-gradient-to-r from-[#030303] via-transparent to-transparent" />

        <button 
          onClick={onBack}
          className="absolute top-24 left-6 md:left-12 p-3 bg-white/10 hover:bg-blue-600 backdrop-blur-xl rounded-full border border-white/10 transition-all z-20 group"
        >
          <ArrowLeft className="w-6 h-6 text-white group-hover:-translate-x-1 transition-transform" />
        </button>
      </div>

      <div className="max-w-7xl mx-auto px-6 lg:px-12 -mt-32 relative z-10 pb-24">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

          <div className="lg:col-span-4 hidden lg:block">
            <div className="sticky top-24">
              <div className="rounded-[2.5rem] overflow-hidden shadow-[0_0_80px_rgba(0,0,0,0.8)] border border-white/10 group">
                <img src={movie.thumbnail} alt={movie.title} className="w-full object-cover group-hover:scale-110 transition-transform duration-700" />
              </div>

              <div className="mt-8 flex gap-4">
                <button 
                  onClick={() => onPlay(movie)}
                  className="flex-1 bg-blue-600 hover:bg-blue-500 text-white py-5 rounded-2xl font-black uppercase tracking-widest text-xs transition-all shadow-xl shadow-blue-600/30 active:scale-95"
                >
                  Watch Now
                </button>
                <button className="p-5 bg-white/5 hover:bg-white/10 border border-white/10 rounded-2xl transition-all active:scale-90">
                  <Plus className="w-5 h-5" />
                </button>
              </div>
            </div>
          </div>

          <div className="lg:col-span-8 space-y-12">
            <div className="space-y-6">
              <div className="flex flex-wrap items-center gap-4">
                <span className="px-3 py-1 bg-blue-600/20 text-blue-400 border border-blue-600/30 rounded-lg text-[10px] font-black uppercase tracking-widest">
                  {movie.duration}
                </span>
                <div className="flex items-center gap-1.5 px-3 py-1 bg-yellow-500 text-black text-[10px] font-black uppercase rounded-lg shadow-lg">
                  <Star className="w-3 h-3 fill-current" />
                  {movie.rating} TMDB
                </div>
                <span className="px-3 py-1 bg-white/5 text-gray-400 border border-white/10 rounded-lg text-[10px] font-black uppercase tracking-widest">
                  {details?.status || 'Analyzing...'}
                </span>
              </div>

              <h1 className="text-5xl md:text-8xl font-black uppercase tracking-tighter italic leading-[0.8] mb-6">
                {movie.title}
              </h1>

              <div className="flex flex-wrap items-center gap-8 text-[11px] font-black text-gray-500 uppercase tracking-[0.3em]">
                <div className="flex items-center gap-2">
                  <Calendar className="w-4 h-4 text-blue-500" />
                  {movie.year}
                </div>
                <div className="flex items-center gap-2">
                  <Clock className="w-4 h-4 text-blue-500" />
                  {details?.runtime ? `${details.runtime} MINS` : '---'}
                </div>
                <div className="flex items-center gap-2">
                  <Globe className="w-4 h-4 text-blue-500" />
                  ORIGINAL LANGUAGE: EN
                </div>
              </div>
            </div>

            {/* AI Verdict Section */}
            <div className="bg-blue-600/5 border border-blue-500/20 rounded-3xl p-8 space-y-4">
               <div className="flex items-center gap-3">
                  <BrainCircuit className="w-5 h-5 text-blue-500" />
                  <span className="text-[10px] font-black uppercase tracking-[0.4em] text-blue-500">CineBlaze AI Verdict</span>
               </div>
               {loadingAi ? (
                 <div className="h-12 w-full bg-white/5 animate-pulse rounded-lg" />
               ) : (
                 <p className="text-xl md:text-2xl font-black italic tracking-tight text-white/90 leading-tight">
                    "{aiVerdict}"
                 </p>
               )}
            </div>

            <div className="space-y-6">
              <h3 className="text-xl font-black uppercase italic border-b border-white/5 pb-4">Database Overview</h3>
              <p className="text-lg md:text-xl text-gray-400 leading-relaxed font-medium">
                {movie.description}
              </p>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-8 py-8 border-y border-white/5">
              <div className="space-y-2">
                <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.3em] text-gray-600">
                  <Users className="w-3 h-3" /> Director
                </div>
                <p className="font-black text-blue-400 uppercase italic">{details?.director || 'Loading...'}</p>
              </div>
              <div className="space-y-2">
                <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.3em] text-gray-600">
                   Producer
                </div>
                <p className="font-bold truncate">{details?.producers.join(', ') || '---'}</p>
              </div>
              <div className="space-y-2">
                <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.3em] text-gray-600">
                  <Wallet className="w-3 h-3" /> Budget
                </div>
                <p className="font-black uppercase tracking-tighter text-gray-300">
                  {details ? formatCurrency(details.budget) : '---'}
                </p>
              </div>
              <div className="space-y-2">
                <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.3em] text-gray-600">
                  <TrendingUp className="w-3 h-3" /> Box Office
                </div>
                <p className="font-black uppercase tracking-tighter text-green-500">
                   {details ? formatCurrency(details.revenue) : '---'}
                </p>
              </div>
            </div>

            <div className="space-y-8">
              <h3 className="text-xl font-black uppercase italic border-b border-white/5 pb-4">Top Billing Cast</h3>
              <div className="grid grid-cols-2 sm:grid-cols-5 gap-6">
                {details?.cast.map((actor) => (
                  <div key={actor.id} className="space-y-4 group cursor-pointer">
                    <div className="aspect-[4/5] rounded-[1.5rem] bg-white/5 border border-white/10 overflow-hidden shadow-xl">
                       {actor.profile_path ? (
                         <img 
                          src={`${TMDB_IMAGE_BASE_URL}/w300${actor.profile_path}`} 
                          className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-700 group-hover:scale-110"
                         />
                       ) : (
                         <div className="w-full h-full flex items-center justify-center text-gray-600 font-black">?</div>
                       )}
                    </div>
                    <div className="text-center px-2">
                      <p className="text-[11px] font-black uppercase truncate italic">{actor.name}</p>
                      <p className="text-[9px] text-gray-600 font-bold uppercase tracking-widest mt-1 truncate">{actor.character}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="pt-12 flex flex-wrap gap-8 border-t border-white/5">
               <button className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-500 hover:text-blue-500 transition-colors">
                  <Share2 className="w-4 h-4" /> Export Database Entry
               </button>
               <button className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-500 hover:text-blue-500 transition-colors">
                  <Award className="w-4 h-4" /> View Full Award History
               </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DetailsPage;

import React, { useState, useEffect, useCallback } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import MovieRow from './components/MovieRow';
import VideoPlayer from './components/VideoPlayer';
import Footer from './components/Footer';
import DetailsPage from './components/DetailsPage';
import { FETCH_URLS, TMDB_IMAGE_BASE_URL, FALLBACK_MOVIE, TMDB_BASE_URL, TMDB_API_KEY } from './constants';
import { Movie, Category } from './types';
import { Flame, Search as SearchIcon, XCircle, Sparkles } from 'lucide-react';

const MOODS = [
  { label: 'Epic & Grand', query: 'adventure epic sci-fi' },
  { label: 'Dark & Gritty', query: 'thriller crime dark' },
  { label: 'Mind-Bending', query: 'mystery psychological sci-fi' },
  { label: 'Feel Good', query: 'comedy animation romance' },
  { label: 'High Octane', query: 'action racing explosion' }
];

const App: React.FC = () => {
  const [selectedMovie, setSelectedMovie] = useState<Movie | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [viewingDetails, setViewingDetails] = useState<Movie | null>(null);
  const [moviesData, setMoviesData] = useState<{ [key: string]: Movie[] }>({});
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<Movie[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [activeMood, setActiveMood] = useState<string | null>(null);

  const mapTMDBToMovie = useCallback((item: any, category: string): Movie => {
    const baseRating = item.vote_average || 0;
    const criticsScore = Math.min(100, Math.max(0, Math.floor(baseRating * 10 + (Math.random() * 10 - 5))));
    const audienceScore = Math.min(100, Math.max(0, Math.floor(baseRating * 10 + (Math.random() * 14 - 7))));

    return {
      id: item.id.toString(),
      title: item.title || item.name || item.original_name || 'Untitled',
      description: item.overview || 'No description available for this cinematic entry.',
      thumbnail: item.poster_path ? `${TMDB_IMAGE_BASE_URL}/w500${item.poster_path}` : FALLBACK_MOVIE.thumbnail,
      heroImage: item.backdrop_path ? `${TMDB_IMAGE_BASE_URL}/original${item.backdrop_path}` : FALLBACK_MOVIE.heroImage,
      year: (item.release_date || item.first_air_date || '').split('-')[0] || '2024',
      rating: baseRating.toFixed(1),
      duration: item.media_type === 'tv' || item.first_air_date ? 'Series' : 'Feature',
      category: category,
      tags: [
        `${criticsScore}% Critics`, 
        `${audienceScore}% Audience`,
        item.vote_count ? `${(item.vote_count / 1000).toFixed(1)}k Votes` : 'Fresh'
      ]
    };
  }, []);

  const fetchSearch = async (query: string) => {
    if (!query.trim()) {
      setIsSearching(false);
      setSearchResults([]);
      return;
    }
    setIsSearching(true);
    setViewingDetails(null);
    try {
      const response = await fetch(`${TMDB_BASE_URL}/search/multi?api_key=${TMDB_API_KEY}&query=${encodeURIComponent(query)}&language=en-US`);
      const data = await response.json();
      setSearchResults(data.results.map((item: any) => mapTMDBToMovie(item, 'Search')));
    } catch (error) {
      console.error('Search error:', error);
    }
  };

  const handleMoodSelect = async (mood: typeof MOODS[0]) => {
    setActiveMood(mood.label);
    setSearchQuery(mood.label);
    fetchSearch(mood.query);
  };

  useEffect(() => {
    const fetchAllData = async () => {
      try {
        const fetchRequests = Object.entries(FETCH_URLS).map(async ([key, url]) => {
          const response = await fetch(url);
          const data = await response.json();
          return {
            key,
            movies: data.results.map((item: any) => mapTMDBToMovie(item, key))
          };
        });

        const results = await Promise.all(fetchRequests);
        const newData: { [key: string]: Movie[] } = {};
        results.forEach(res => {
          newData[res.key] = res.movies;
        });
        setMoviesData(newData);
        setTimeout(() => setLoading(false), 1200);
      } catch (error) {
        console.error('Error fetching data:', error);
        setLoading(false);
      }
    };

    fetchAllData();
  }, [mapTMDBToMovie]);

  const handlePlay = (movie: Movie) => {
    setSelectedMovie(movie);
    setIsPlaying(true);
  };

  const handleOpenDetails = (movie: Movie) => {
    setViewingDetails(movie);
    setIsSearching(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const clearSearch = () => {
    setSearchQuery('');
    setSearchResults([]);
    setIsSearching(false);
    setActiveMood(null);
  };

  const heroMovie = moviesData.trending?.[0] || FALLBACK_MOVIE;
  const spotlightMovie = moviesData.originals?.[2] || moviesData.topRated?.[0] || FALLBACK_MOVIE;

  if (loading) {
    return (
      <div className="bg-[#030303] min-h-screen flex items-center justify-center">
        <div className="flex flex-col items-center gap-6">
          <div className="flex items-center gap-3 animate-pulse">
            <div className="p-2 bg-blue-600 rounded-xl shadow-2xl shadow-blue-600/50">
               <Flame className="w-10 h-10 text-white fill-current" />
            </div>
            <h1 className="text-4xl font-black text-white tracking-tighter uppercase italic">CINE<span className="text-blue-500">BLAZE</span></h1>
          </div>
          <div className="flex flex-col items-center gap-2">
            <div className="w-64 h-1 bg-white/5 rounded-full overflow-hidden">
              <div className="h-full bg-blue-600 animate-[loading_1.5s_ease-in-out_infinite] shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
            </div>
            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-500 text-center">Calibrating Cinematic Database...</span>
          </div>
        </div>
        <style>{`
          @keyframes loading {
            0% { transform: translateX(-100%); width: 30%; }
            50% { width: 60%; }
            100% { transform: translateX(350%); width: 30%; }
          }
        `}</style>
      </div>
    );
  }

  return (
    <div className="bg-[#030303] min-h-screen text-white overflow-hidden selection:bg-blue-600 selection:text-white">
      <Navbar 
        onSearch={fetchSearch} 
        searchQuery={searchQuery} 
        setSearchQuery={setSearchQuery} 
        onHomeClick={() => { setViewingDetails(null); clearSearch(); }}
      />

      <main className="relative pb-24">
        {viewingDetails ? (
          <DetailsPage 
            movie={viewingDetails} 
            onBack={() => setViewingDetails(null)} 
            onPlay={handlePlay} 
          />
        ) : isSearching ? (
          <div className="pt-32 px-6 lg:px-12 min-h-screen">
            <div className="flex flex-col md:flex-row md:items-end justify-between mb-12 border-b border-white/5 pb-8 gap-6">
              <div>
                <h2 className="text-4xl md:text-6xl font-black uppercase tracking-tighter italic leading-none">
                   {activeMood ? `Discover: ${activeMood}` : 'Database Search'}
                </h2>
                <p className="text-gray-500 uppercase tracking-widest text-[10px] font-black mt-4">Entries found for: <span className="text-blue-500">"{searchQuery}"</span></p>
              </div>
              <button 
                onClick={clearSearch}
                className="flex items-center gap-2 px-6 py-3 bg-white/5 hover:bg-red-600/20 hover:text-red-500 rounded-full text-xs font-black uppercase tracking-widest transition-all border border-white/5"
              >
                <XCircle className="w-4 h-4" />
                Reset Filter
              </button>
            </div>

            {searchResults.length > 0 ? (
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-8">
                {searchResults.map((movie) => (
                  <div key={movie.id} onClick={() => handleOpenDetails(movie)} className="relative group cursor-pointer transition-transform duration-500 hover:scale-105">
                     <div className="aspect-[2/3] rounded-2xl overflow-hidden mb-4 border border-white/5 group-hover:border-blue-500/50 transition-all shadow-xl group-hover:shadow-blue-600/20">
                        <img src={movie.thumbnail} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center backdrop-blur-sm">
                           <div className="p-4 bg-blue-600 rounded-full shadow-2xl scale-0 group-hover:scale-100 transition-transform">
                             <SearchIcon className="w-6 h-6" />
                           </div>
                        </div>
                     </div>
                     <h3 className="text-sm font-black truncate uppercase italic">{movie.title}</h3>
                     <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">{movie.year} • {movie.rating} TMDB SCORE</p>
                  </div>
                ))}
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-32 opacity-20">
                <SearchIcon className="w-24 h-24 mb-6" />
                <h3 className="text-2xl font-black uppercase italic">No entries found in our database</h3>
              </div>
            )}
          </div>
        ) : (
          <>
            <Hero movie={heroMovie} onPlay={handleOpenDetails} />

            <div className="relative -mt-24 z-10 space-y-16">
              {/* Mood Scout Feature */}
              <div className="px-6 lg:px-12">
                 <div className="flex flex-col md:flex-row items-center gap-8 bg-blue-600/5 border border-blue-500/10 p-8 rounded-[2.5rem] backdrop-blur-xl">
                    <div className="flex items-center gap-4">
                       <div className="p-3 bg-blue-600 rounded-2xl shadow-lg shadow-blue-600/30">
                          <Sparkles className="w-6 h-6 text-white" />
                       </div>
                       <div>
                          <h4 className="text-xl font-black uppercase italic tracking-tighter">AI Mood Scout</h4>
                          <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Discover by Vibe</p>
                       </div>
                    </div>
                    <div className="h-px w-full md:w-px md:h-12 bg-white/10"></div>
                    <div className="flex flex-wrap gap-3">
                       {MOODS.map((mood) => (
                         <button
                           key={mood.label}
                           onClick={() => handleMoodSelect(mood)}
                           className="px-6 py-2.5 bg-white/5 hover:bg-blue-600 text-white border border-white/10 hover:border-blue-500 rounded-full text-[10px] font-black uppercase tracking-widest transition-all active:scale-95 shadow-md"
                         >
                           {mood.label}
                         </button>
                       ))}
                    </div>
                 </div>
              </div>

              {moviesData.trending && (
                <MovieRow 
                  title={Category.TRENDING} 
                  movies={moviesData.trending} 
                  onPlay={handleOpenDetails}
                />
              )}

              {moviesData.originals && (
                <MovieRow 
                  title={Category.ORIGINALS} 
                  movies={moviesData.originals} 
                  onPlay={handleOpenDetails}
                />
              )}

              {/* Spotlight Section */}
              <div className="px-6 lg:px-12 my-32">
                <div className="relative h-[65vh] rounded-[3rem] overflow-hidden group shadow-[0_40px_100px_rgba(0,0,0,0.5)] border border-white/5">
                  <div 
                    className="absolute inset-0 bg-cover bg-center transition-transform duration-[2000ms] group-hover:scale-110"
                    style={{ backgroundImage: `url(${spotlightMovie.heroImage})` }}
                  />
                  <div className="absolute inset-0 bg-gradient-to-r from-black via-black/70 to-transparent p-16 flex flex-col justify-center max-w-2xl">
                    <div className="flex items-center gap-4 mb-6">
                      <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-600/40">
                        <Flame className="w-5 h-5 text-white fill-current" />
                      </div>
                      <span className="text-blue-400 font-black tracking-[0.5em] text-[10px] uppercase">Database Spotlight</span>
                    </div>
                    <h2 className="text-6xl md:text-8xl font-black mb-8 uppercase tracking-tighter leading-none italic group-hover:text-blue-500 transition-colors duration-700">
                      {spotlightMovie.title}
                    </h2>
                    <div className="flex items-center gap-8 mb-10">
                       <div className="flex flex-col">
                          <span className="text-[10px] font-black text-gray-500 uppercase tracking-[0.3em]">TMDB Score</span>
                          <span className="text-3xl font-black italic text-blue-500">{spotlightMovie.rating}</span>
                       </div>
                       <div className="w-px h-12 bg-white/10"></div>
                       <div className="flex flex-col">
                          <span className="text-[10px] font-black text-gray-500 uppercase tracking-[0.3em]">Critical Consensus</span>
                          <span className="text-3xl font-black italic text-green-500">{spotlightMovie.tags[0]}</span>
                       </div>
                    </div>
                    <p className="text-xl text-gray-300 mb-12 leading-relaxed line-clamp-3 font-medium drop-shadow-lg opacity-80">
                      {spotlightMovie.description}
                    </p>
                    <div className="flex gap-6">
                      <button 
                        onClick={() => handleOpenDetails(spotlightMovie)}
                        className="bg-blue-600 hover:bg-blue-500 text-white px-12 py-5 rounded-full font-black uppercase tracking-widest text-[11px] transition-all transform hover:scale-105 active:scale-95 shadow-2xl shadow-blue-600/50"
                      >
                        Explore Database
                      </button>
                      <button className="bg-white/5 backdrop-blur-xl hover:bg-white/10 text-white px-12 py-5 rounded-full font-black uppercase tracking-widest text-[11px] transition-all border border-white/10">
                        Official Trailer
                      </button>
                    </div>
                  </div>
                </div>
              </div>

              {moviesData.topRated && (
                <MovieRow 
                  title={Category.TOP_RATED} 
                  movies={moviesData.topRated} 
                  onPlay={handleOpenDetails}
                />
              )}

              {moviesData.actionMovies && (
                <MovieRow 
                  title={Category.ACTION} 
                  movies={moviesData.actionMovies} 
                  onPlay={handleOpenDetails}
                />
              )}

              {moviesData.comedyMovies && (
                <MovieRow 
                  title={Category.COMEDY} 
                  movies={moviesData.comedyMovies} 
                  onPlay={handleOpenDetails}
                />
              )}
            </div>
          </>
        )}
      </main>

      <Footer />

      {isPlaying && selectedMovie && (
        <VideoPlayer 
          movie={selectedMovie} 
          onClose={() => setIsPlaying(false)} 
        />
      )}
    </div>
  );
};

export default App;

