import { Movie } from './types';

export const TMDB_API_KEY = '04c0c144af4c62289082187c53fdaddb';
export const TMDB_BASE_URL = 'https://api.themoviedb.org/3';
export const TMDB_IMAGE_BASE_URL = 'https://image.tmdb.org/t/p';

export const FETCH_URLS = {
  trending: `${TMDB_BASE_URL}/trending/all/week?api_key=${TMDB_API_KEY}&language=en-US`,
  originals: `${TMDB_BASE_URL}/discover/tv?api_key=${TMDB_API_KEY}&with_networks=213`,
  topRated: `${TMDB_BASE_URL}/movie/top_rated?api_key=${TMDB_API_KEY}&language=en-US`,
  actionMovies: `${TMDB_BASE_URL}/discover/movie?api_key=${TMDB_API_KEY}&with_genres=28`,
  comedyMovies: `${TMDB_BASE_URL}/discover/movie?api_key=${TMDB_API_KEY}&with_genres=35`,
  horrorMovies: `${TMDB_BASE_URL}/discover/movie?api_key=${TMDB_API_KEY}&with_genres=27`,
