};

import React, { useState, useEffect } from 'react';
import { Search, Bell, Menu, User, X, Flame } from 'lucide-react';
import { Section } from '../types';

interface NavbarProps {
  onSearch: (query: string) => void;
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  onHomeClick: () => void;
  onSectionClick: (section: Section) => void;
  activeSection: Section;
}

const Navbar: React.FC<NavbarProps> = ({ onSearch, searchQuery, setSearchQuery, onHomeClick, onSectionClick, activeSection }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isSearchActive, setIsSearchActive] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 0);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSearch(searchQuery);
  };

  const handleLinkClick = (section: Section) => {
    onSectionClick(section);
    setIsMobileMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <nav className={`fixed top-0 w-full z-[80] transition-all duration-300 px-6 lg:px-12 py-4 flex items-center justify-between ${isScrolled || isSearchActive ? 'bg-black/95 backdrop-blur-xl border-b border-white/5' : 'bg-transparent'}`}>
      <div className="flex items-center gap-10">
        <div onClick={() => handleLinkClick('home')} className="flex items-center gap-2 group cursor-pointer active:scale-95 transition-transform">
          <div className="p-1.5 bg-blue-600 rounded-lg group-hover:bg-blue-500 transition-colors shadow-lg shadow-blue-600/20">
            <Flame className="w-6 h-6 text-white fill-current" />
          </div>
          <h1 className="text-2xl font-black text-white tracking-tighter uppercase italic">CINE<span className="text-blue-500">BLAZE</span></h1>
        </div>

        <ul className="hidden md:flex items-center gap-6 text-[10px] font-black uppercase tracking-widest">
          <li onClick={() => handleLinkClick('home')} className={`cursor-pointer transition-colors ${activeSection === 'home' ? 'text-blue-500' : 'text-gray-500 hover:text-white'}`}>Home</li>
          <li onClick={() => handleLinkClick('movies')} className={`cursor-pointer transition-colors ${activeSection === 'movies' ? 'text-blue-500' : 'text-gray-500 hover:text-white'}`}>Movies</li>
          <li onClick={() => handleLinkClick('tv')} className={`cursor-pointer transition-colors ${activeSection === 'tv' ? 'text-blue-500' : 'text-gray-500 hover:text-white'}`}>TV Series</li>
          <li onClick={() => handleLinkClick('people')} className={`cursor-pointer transition-colors ${activeSection === 'people' ? 'text-blue-500' : 'text-gray-500 hover:text-white'}`}>People</li>
          <li onClick={() => handleLinkClick('awards')} className={`cursor-pointer transition-colors ${activeSection === 'awards' ? 'text-blue-500' : 'text-gray-500 hover:text-white'}`}>Awards</li>
        </ul>
      </div>

      <div className="flex items-center gap-6">
        <form onSubmit={handleSearchSubmit} className={`relative transition-all duration-500 ${isSearchActive ? 'w-64 md:w-96' : 'w-40 md:w-56'}`}>
          <div className={`flex items-center border rounded-full px-4 py-2 transition-all ${isSearchActive ? 'bg-white/10 border-blue-500/50' : 'bg-white/5 border-white/10 hover:bg-white/10'}`}>
            <Search className={`w-4 h-4 transition-colors ${isSearchActive ? 'text-blue-500' : 'text-gray-400'}`} />
            <input 
              type="text"
              placeholder="Search database..."
              value={searchQuery}
              onFocus={() => setIsSearchActive(true)}
              onBlur={() => !searchQuery && setIsSearchActive(false)}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                if (e.target.value.length > 2) onSearch(e.target.value);
                if (e.target.value.length === 0) onSearch('');
              }}
              className="bg-transparent border-none outline-none text-xs text-white placeholder:text-gray-500 ml-3 w-full font-bold tracking-tight"
            />
          </div>
        </form>

        <div className="hidden sm:flex items-center gap-6">
          <Bell className="w-5 h-5 text-gray-400 hover:text-blue-500 cursor-pointer transition-colors" />
          <div className="w-9 h-9 rounded-full bg-gradient-to-tr from-blue-700 to-blue-500 flex items-center justify-center text-[10px] font-black shadow-lg shadow-blue-900/40 cursor-pointer hover:ring-2 hover:ring-blue-400 transition-all">
            JD
          </div>
        </div>

        <button 
          className="md:hidden p-2 hover:bg-white/5 rounded-full transition-colors"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="absolute top-full left-0 w-full bg-black/98 border-b border-white/5 p-8 flex flex-col gap-6 md:hidden shadow-2xl backdrop-blur-3xl">
          <button onClick={() => handleLinkClick('home')} className={`text-xl font-black uppercase italic text-left ${activeSection === 'home' ? 'text-blue-500' : 'text-gray-400'}`}>Home</button>
          <button onClick={() => handleLinkClick('movies')} className={`text-xl font-black uppercase italic text-left ${activeSection === 'movies' ? 'text-blue-500' : 'text-gray-400'}`}>Movies</button>
          <button onClick={() => handleLinkClick('tv')} className={`text-xl font-black uppercase italic text-left ${activeSection === 'tv' ? 'text-blue-500' : 'text-gray-400'}`}>TV Series</button>
          <button onClick={() => handleLinkClick('people')} className={`text-xl font-black uppercase italic text-left ${activeSection === 'people' ? 'text-blue-500' : 'text-gray-400'}`}>People</button>
          <button onClick={() => handleLinkClick('awards')} className={`text-xl font-black uppercase italic text-left ${activeSection === 'awards' ? 'text-blue-500' : 'text-gray-400'}`}>Awards</button>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React, { useState, useEffect, useCallback } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import MovieRow from './components/MovieRow';
import VideoPlayer from './components/VideoPlayer';
import Footer from './components/Footer';
import DetailsPage from './components/DetailsPage';
import { FETCH_URLS, TMDB_IMAGE_BASE_URL, FALLBACK_MOVIE, TMDB_BASE_URL, TMDB_API_KEY } from './constants';
import { Movie, Category, Section, Person } from './types';
import { Flame, Search as SearchIcon, XCircle, Sparkles, Users } from 'lucide-react';

const MOODS = [
  { label: 'Epic & Grand', query: 'adventure epic sci-fi' },
  { label: 'Dark & Gritty', query: 'thriller crime dark' },
  { label: 'Mind-Bending', query: 'mystery psychological sci-fi' },
  { label: 'Feel Good', query: 'comedy animation romance' },
  { label: 'High Octane', query: 'action racing explosion' }
];

const App: React.FC = () => {
  const [selectedMovie, setSelectedMovie] = useState<Movie | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [viewingDetails, setViewingDetails] = useState<Movie | null>(null);
  const [moviesData, setMoviesData] = useState<{ [key: string]: Movie[] }>({});
  const [peopleData, setPeopleData] = useState<Person[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<Movie[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [activeMood, setActiveMood] = useState<string | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('home');

  const mapTMDBToMovie = useCallback((item: any, category: string): Movie => {
    const baseRating = item.vote_average || 0;
    const criticsScore = Math.min(100, Math.max(0, Math.floor(baseRating * 10 + (Math.random() * 10 - 5))));
    const audienceScore = Math.min(100, Math.max(0, Math.floor(baseRating * 10 + (Math.random() * 14 - 7))));

    return {
      id: item.id.toString(),
      title: item.title || item.name || item.original_name || 'Untitled',
      description: item.overview || 'No description available for this cinematic entry.',
      thumbnail: item.poster_path ? `${TMDB_IMAGE_BASE_URL}/w500${item.poster_path}` : FALLBACK_MOVIE.thumbnail,
      heroImage: item.backdrop_path ? `${TMDB_IMAGE_BASE_URL}/original${item.backdrop_path}` : FALLBACK_MOVIE.heroImage,
      year: (item.release_date || item.first_air_date || '').split('-')[0] || '2024',
      rating: baseRating.toFixed(1),
      duration: item.media_type === 'tv' || item.first_air_date ? 'Series' : 'Feature',
      category: category,
      tags: [
        `${criticsScore}% Critics`, 
        `${audienceScore}% Audience`,
        item.vote_count ? `${(item.vote_count / 1000).toFixed(1)}k Votes` : 'Fresh'
      ]
    };
  }, []);

  const fetchSearch = async (query: string) => {
    if (!query.trim()) {
      setIsSearching(false);
      setSearchResults([]);
      return;
    }
    setIsSearching(true);
    setViewingDetails(null);
    setActiveSection('home');
    try {
      const response = await fetch(`${TMDB_BASE_URL}/search/multi?api_key=${TMDB_API_KEY}&query=${encodeURIComponent(query)}&language=en-US`);
      const data = await response.json();
      setSearchResults(data.results.map((item: any) => mapTMDBToMovie(item, 'Search')));
    } catch (error) {
      console.error('Search error:', error);
    }
  };

  useEffect(() => {
    const fetchAllData = async () => {
      try {
        const fetchRequests = Object.entries(FETCH_URLS).map(async ([key, url]) => {
          const response = await fetch(url);
          const data = await response.json();
          if (key === 'popularPeople') {
            return { key, people: data.results };
          }
          return {
            key,
            movies: data.results.map((item: any) => mapTMDBToMovie(item, key))
          };
        });

        const results = await Promise.all(fetchRequests);
        const newData: { [key: string]: Movie[] } = {};
        results.forEach(res => {
          if ('movies' in res) newData[res.key] = res.movies;
          if ('people' in res) {
            setPeopleData(res.people.map((p: any) => ({
              id: p.id.toString(),
              name: p.name,
              known_for_department: p.known_for_department,
              profile_path: p.profile_path,
              known_for: p.known_for?.map((m: any) => m.title || m.name).join(', ') || 'Various'
            })));
          }
        });
        setMoviesData(newData);
        setTimeout(() => setLoading(false), 1200);
      } catch (error) {
        console.error('Error fetching data:', error);
        setLoading(false);
      }
    };

    fetchAllData();
  }, [mapTMDBToMovie]);

  const handleOpenDetails = (movie: Movie) => {
    setViewingDetails(movie);
    setIsSearching(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const clearSearch = () => {
    setSearchQuery('');
    setSearchResults([]);
    setIsSearching(false);
    setActiveMood(null);
  };

  const handleSectionChange = (section: Section) => {
    setActiveSection(section);
    setViewingDetails(null);
    clearSearch();
  };

  if (loading) {
    return (
      <div className="bg-[#030303] min-h-screen flex items-center justify-center">
        <div className="flex flex-col items-center gap-6">
          <div className="flex items-center gap-3 animate-pulse">
            <div className="p-2 bg-blue-600 rounded-xl shadow-2xl shadow-blue-600/50">
               <Flame className="w-10 h-10 text-white fill-current" />
            </div>
            <h1 className="text-4xl font-black text-white tracking-tighter uppercase italic">CINE<span className="text-blue-500">BLAZE</span></h1>
          </div>
          <span className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-500">Initializing Database...</span>
        </div>
      </div>
    );
  }

  const renderSectionGrid = (title: string, items: any[], type: 'movie' | 'person' = 'movie') => (
    <div className="pt-32 px-6 lg:px-12 min-h-screen">
      <div className="mb-12 border-b border-white/5 pb-8">
        <h2 className="text-4xl md:text-6xl font-black uppercase tracking-tighter italic leading-none">{title}</h2>
        <p className="text-gray-500 uppercase tracking-widest text-[10px] font-black mt-4">Database Records: <span className="text-blue-500">{items.length} Entries</span></p>
      </div>
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-8">
        {items.map((item) => (
          <div 
            key={item.id} 
            onClick={() => type === 'movie' ? handleOpenDetails(item) : null}
            className={`relative group ${type === 'movie' ? 'cursor-pointer' : 'cursor-default'} transition-transform duration-500 hover:scale-105`}
          >
            <div className="aspect-[2/3] rounded-2xl overflow-hidden mb-4 border border-white/5 group-hover:border-blue-500/50 transition-all shadow-xl">
              <img 
                src={type === 'movie' ? item.thumbnail : (item.profile_path ? `${TMDB_IMAGE_BASE_URL}/w500${item.profile_path}` : 'https://via.placeholder.com/500x750?text=No+Photo')} 
                className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" 
              />
              {type === 'movie' && (
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center backdrop-blur-sm">
                   <div className="p-4 bg-blue-600 rounded-full shadow-2xl scale-0 group-hover:scale-100 transition-transform">
                     <SearchIcon className="w-6 h-6" />
                   </div>
                </div>
              )}
            </div>
            <h3 className="text-sm font-black truncate uppercase italic">{type === 'movie' ? item.title : item.name}</h3>
            <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">
              {type === 'movie' ? `${item.year} • ${item.rating} SCORE` : item.known_for_department}
            </p>
            {type === 'person' && (
              <p className="text-[9px] text-gray-600 font-medium truncate mt-1 italic">{item.known_for}</p>
            )}
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="bg-[#030303] min-h-screen text-white overflow-hidden selection:bg-blue-600 selection:text-white">
      <Navbar 
        onSearch={fetchSearch} 
        searchQuery={searchQuery} 
        setSearchQuery={setSearchQuery} 
        onHomeClick={() => handleSectionChange('home')}
        onSectionClick={handleSectionChange}
        activeSection={activeSection}
      />

      <main className="relative pb-24">
        {viewingDetails ? (
          <DetailsPage 
            movie={viewingDetails} 
            onBack={() => setViewingDetails(null)} 
            onPlay={(movie) => { setSelectedMovie(movie); setIsPlaying(true); }} 
          />
        ) : isSearching ? (
          renderSectionGrid(`Search: ${searchQuery}`, searchResults)
        ) : activeSection === 'movies' ? (
          renderSectionGrid('All Movies', moviesData.allMovies || [])
        ) : activeSection === 'tv' ? (
          renderSectionGrid('TV Series Database', moviesData.allTV || [])
        ) : activeSection === 'people' ? (
          renderSectionGrid('Popular Talent', peopleData, 'person')
        ) : activeSection === 'awards' ? (
          renderSectionGrid('Hall of Fame', moviesData.topRated || [])
        ) : (
          <>
            <Hero movie={moviesData.trending?.[0] || FALLBACK_MOVIE} onPlay={handleOpenDetails} />

            <div className="relative -mt-24 z-10 space-y-16">
              {/* Mood Scout Feature */}
              <div className="px-6 lg:px-12">
                 <div className="flex flex-col md:flex-row items-center gap-8 bg-blue-600/5 border border-blue-500/10 p-8 rounded-[2.5rem] backdrop-blur-xl">
                    <div className="flex items-center gap-4">
                       <div className="p-3 bg-blue-600 rounded-2xl shadow-lg shadow-blue-600/30">
                          <Sparkles className="w-6 h-6 text-white" />
                       </div>
                       <div>
                          <h4 className="text-xl font-black uppercase italic tracking-tighter">AI Mood Scout</h4>
                          <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Discover by Vibe</p>
                       </div>
                    </div>
                    <div className="h-px w-full md:w-px md:h-12 bg-white/10"></div>
                    <div className="flex flex-wrap gap-3">
                       {MOODS.map((mood) => (
                         <button
                           key={mood.label}
                           onClick={() => { setActiveMood(mood.label); setSearchQuery(mood.label); fetchSearch(mood.query); }}
                           className="px-6 py-2.5 bg-white/5 hover:bg-blue-600 text-white border border-white/10 hover:border-blue-500 rounded-full text-[10px] font-black uppercase tracking-widest transition-all active:scale-95 shadow-md"
                         >
                           {mood.label}
                         </button>
                       ))}
                    </div>
                 </div>
              </div>

              {moviesData.trending && (
                <MovieRow title={Category.TRENDING} movies={moviesData.trending} onPlay={handleOpenDetails} />
              )}

              {moviesData.originals && (
                <MovieRow title={Category.ORIGINALS} movies={moviesData.originals} onPlay={handleOpenDetails} />
              )}

              {/* Spotlight Section */}
              <div className="px-6 lg:px-12 my-32">
                <div className="relative h-[65vh] rounded-[3rem] overflow-hidden group shadow-2xl border border-white/5">
                  <div 
                    className="absolute inset-0 bg-cover bg-center transition-transform duration-[2000ms] group-hover:scale-110"
                    style={{ backgroundImage: `url(${(moviesData.topRated?.[0] || FALLBACK_MOVIE).heroImage})` }}
                  />
                  <div className="absolute inset-0 bg-gradient-to-r from-black via-black/70 to-transparent p-16 flex flex-col justify-center max-w-2xl">
                    <div className="flex items-center gap-4 mb-6">
                      <div className="bg-blue-600 p-2 rounded-lg">
                        <Flame className="w-5 h-5 text-white fill-current" />
                      </div>
                      <span className="text-blue-400 font-black tracking-[0.5em] text-[10px] uppercase">Cinema Hall of Fame</span>
                    </div>
                    <h2 className="text-6xl md:text-8xl font-black mb-8 uppercase tracking-tighter leading-none italic">
                      {(moviesData.topRated?.[0] || FALLBACK_MOVIE).title}
                    </h2>
                    <div className="flex gap-6">
                      <button 
                        onClick={() => handleOpenDetails(moviesData.topRated?.[0] || FALLBACK_MOVIE)}
                        className="bg-blue-600 hover:bg-blue-500 text-white px-12 py-5 rounded-full font-black uppercase tracking-widest text-[11px] transition-all transform hover:scale-105 active:scale-95 shadow-2xl"
                      >
                        Explore Entry
                      </button>
                    </div>
                  </div>
                </div>
              </div>

              {moviesData.actionMovies && (
                <MovieRow title={Category.ACTION} movies={moviesData.actionMovies} onPlay={handleOpenDetails} />
              )}
            </div>
          </>
        )}
      </main>

      <Footer />

      {isPlaying && selectedMovie && (
        <VideoPlayer 
          movie={selectedMovie} 
          onClose={() => setIsPlaying(false)} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import MovieRow from './components/MovieRow';
import VideoPlayer from './components/VideoPlayer';
import Footer from './components/Footer';
import DetailsPage from './components/DetailsPage';
import PersonDetailsPage from './components/PersonDetailsPage';
import { FETCH_URLS, TMDB_IMAGE_BASE_URL, FALLBACK_MOVIE, TMDB_BASE_URL, TMDB_API_KEY } from './constants';
import { Movie, Category, Section, Person } from './types';
import { Flame, Search as SearchIcon, XCircle, Sparkles, Users } from 'lucide-react';

const MOODS = [
  { label: 'Epic & Grand', query: 'adventure epic sci-fi' },
  { label: 'Dark & Gritty', query: 'thriller crime dark' },
  { label: 'Mind-Bending', query: 'mystery psychological sci-fi' },
  { label: 'Feel Good', query: 'comedy animation romance' },
  { label: 'High Octane', query: 'action racing explosion' }
];

const App: React.FC = () => {
  const [selectedMovie, setSelectedMovie] = useState<Movie | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [viewingDetails, setViewingDetails] = useState<Movie | null>(null);
  const [viewingPerson, setViewingPerson] = useState<Person | null>(null);
  const [moviesData, setMoviesData] = useState<{ [key: string]: Movie[] }>({});
  const [peopleData, setPeopleData] = useState<Person[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<Movie[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [activeMood, setActiveMood] = useState<string | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('home');

  const mapTMDBToMovie = useCallback((item: any, category: string): Movie => {
    const baseRating = item.vote_average || 0;
    const criticsScore = Math.min(100, Math.max(0, Math.floor(baseRating * 10 + (Math.random() * 10 - 5))));
    const audienceScore = Math.min(100, Math.max(0, Math.floor(baseRating * 10 + (Math.random() * 14 - 7))));

    return {
      id: item.id.toString(),
      title: item.title || item.name || item.original_name || 'Untitled',
      description: item.overview || 'No description available for this cinematic entry.',
      thumbnail: item.poster_path ? `${TMDB_IMAGE_BASE_URL}/w500${item.poster_path}` : FALLBACK_MOVIE.thumbnail,
      heroImage: item.backdrop_path ? `${TMDB_IMAGE_BASE_URL}/original${item.backdrop_path}` : FALLBACK_MOVIE.heroImage,
      year: (item.release_date || item.first_air_date || '').split('-')[0] || '2024',
      rating: baseRating.toFixed(1),
      duration: item.media_type === 'tv' || item.first_air_date ? 'Series' : 'Feature',
      category: category,
      tags: [
        `${criticsScore}% Critics`, 
        `${audienceScore}% Audience`,
        item.vote_count ? `${(item.vote_count / 1000).toFixed(1)}k Votes` : 'Fresh'
      ]
    };
  }, []);

  const fetchSearch = async (query: string) => {
    if (!query.trim()) {
      setIsSearching(false);
      setSearchResults([]);
      return;
    }
    setIsSearching(true);
    setViewingDetails(null);
    setViewingPerson(null);
    setActiveSection('home');
    try {
      const response = await fetch(`${TMDB_BASE_URL}/search/multi?api_key=${TMDB_API_KEY}&query=${encodeURIComponent(query)}&language=en-US`);
      const data = await response.json();
      setSearchResults(data.results.map((item: any) => mapTMDBToMovie(item, 'Search')));
    } catch (error) {
      console.error('Search error:', error);
    }
  };

  useEffect(() => {
    const fetchAllData = async () => {
      try {
        const fetchRequests = Object.entries(FETCH_URLS).map(async ([key, url]) => {
          const response = await fetch(url);
          const data = await response.json();
          if (key === 'popularPeople') {
            return { key, people: data.results };
          }
          return {
            key,
            movies: data.results.map((item: any) => mapTMDBToMovie(item, key))
          };
        });

        const results = await Promise.all(fetchRequests);
        const newData: { [key: string]: Movie[] } = {};
        results.forEach(res => {
          if ('movies' in res) newData[res.key] = res.movies;
          if ('people' in res) {
            setPeopleData(res.people.map((p: any) => ({
              id: p.id.toString(),
              name: p.name,
              known_for_department: p.known_for_department,
              profile_path: p.profile_path,
              known_for: p.known_for?.map((m: any) => m.title || m.name).join(', ') || 'Various'
            })));
          }
        });
        setMoviesData(newData);
        setTimeout(() => setLoading(false), 1200);
      } catch (error) {
        console.error('Error fetching data:', error);
        setLoading(false);
      }
    };

    fetchAllData();
  }, [mapTMDBToMovie]);

  const handleOpenDetails = (movie: Movie) => {
    setViewingDetails(movie);
    setViewingPerson(null);
    setIsSearching(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleOpenPerson = (person: Person) => {
    setViewingPerson(person);
    setViewingDetails(null);
    setIsSearching(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const clearSearch = () => {
    setSearchQuery('');
    setSearchResults([]);
    setIsSearching(false);
    setActiveMood(null);
  };

  const handleSectionChange = (section: Section) => {
    setActiveSection(section);
    setViewingDetails(null);
    setViewingPerson(null);
    clearSearch();
  };

  if (loading) {
    return (
      <div className="bg-[#030303] min-h-screen flex items-center justify-center">
        <div className="flex flex-col items-center gap-6">
          <div className="flex items-center gap-3 animate-pulse">
            <div className="p-2 bg-blue-600 rounded-xl shadow-2xl shadow-blue-600/50">
               <Flame className="w-10 h-10 text-white fill-current" />
            </div>
            <h1 className="text-4xl font-black text-white tracking-tighter uppercase italic">CINE<span className="text-blue-500">BLAZE</span></h1>
          </div>
          <span className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-500">Initializing Database...</span>
        </div>
      </div>
    );
  }

  const renderSectionGrid = (title: string, items: any[], type: 'movie' | 'person' = 'movie') => (
    <div className="pt-32 px-6 lg:px-12 min-h-screen">
      <div className="mb-12 border-b border-white/5 pb-8">
        <h2 className="text-4xl md:text-6xl font-black uppercase tracking-tighter italic leading-none">{title}</h2>
        <p className="text-gray-500 uppercase tracking-widest text-[10px] font-black mt-4">Database Records: <span className="text-blue-500">{items.length} Entries</span></p>
      </div>
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-8">
        {items.map((item) => (
          <div 
            key={item.id} 
            onClick={() => type === 'movie' ? handleOpenDetails(item) : handleOpenPerson(item)}
            className={`relative group cursor-pointer transition-transform duration-500 hover:scale-105`}
          >
            <div className="aspect-[2/3] rounded-2xl overflow-hidden mb-4 border border-white/5 group-hover:border-blue-500/50 transition-all shadow-xl">
              <img 
                src={type === 'movie' ? item.thumbnail : (item.profile_path ? `${TMDB_IMAGE_BASE_URL}/w500${item.profile_path}` : 'https://via.placeholder.com/500x750?text=No+Photo')} 
                className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" 
              />
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center backdrop-blur-sm">
                 <div className="p-4 bg-blue-600 rounded-full shadow-2xl scale-0 group-hover:scale-100 transition-transform">
                   <SearchIcon className="w-6 h-6" />
                 </div>
              </div>
            </div>
            <h3 className="text-sm font-black truncate uppercase italic">{type === 'movie' ? item.title : item.name}</h3>
            <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">
              {type === 'movie' ? `${item.year} • ${item.rating} SCORE` : item.known_for_department}
            </p>
            {type === 'person' && (
              <p className="text-[9px] text-gray-600 font-medium truncate mt-1 italic">{item.known_for}</p>
            )}
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="bg-[#030303] min-h-screen text-white overflow-hidden selection:bg-blue-600 selection:text-white">
      <Navbar 
        onSearch={fetchSearch} 
        searchQuery={searchQuery} 
        setSearchQuery={setSearchQuery} 
        onHomeClick={() => handleSectionChange('home')}
        onSectionClick={handleSectionChange}
        activeSection={activeSection}
      />

      <main className="relative pb-24">
        {viewingDetails ? (
          <DetailsPage 
            movie={viewingDetails} 
            onBack={() => setViewingDetails(null)} 
            onPlay={(movie) => { setSelectedMovie(movie); setIsPlaying(true); }} 
          />
        ) : viewingPerson ? (
          <PersonDetailsPage 
            person={viewingPerson} 
            onBack={() => setViewingPerson(null)} 
            onMovieClick={handleOpenDetails}
          />
        ) : isSearching ? (
          renderSectionGrid(`Search: ${searchQuery}`, searchResults)
        ) : activeSection === 'movies' ? (
          renderSectionGrid('All Movies', moviesData.allMovies || [])
        ) : activeSection === 'tv' ? (
          renderSectionGrid('TV Series Database', moviesData.allTV || [])
        ) : activeSection === 'people' ? (
          renderSectionGrid('Popular Talent', peopleData, 'person')
        ) : activeSection === 'awards' ? (
          renderSectionGrid('Hall of Fame', moviesData.topRated || [])
        ) : (
          <>
            <Hero movie={moviesData.trending?.[0] || FALLBACK_MOVIE} onPlay={handleOpenDetails} />

            <div className="relative -mt-24 z-10 space-y-16">
              <div className="px-6 lg:px-12">
                 <div className="flex flex-col md:flex-row items-center gap-8 bg-blue-600/5 border border-blue-500/10 p-8 rounded-[2.5rem] backdrop-blur-xl">
                    <div className="flex items-center gap-4">
                       <div className="p-3 bg-blue-600 rounded-2xl shadow-lg shadow-blue-600/30">
                          <Sparkles className="w-6 h-6 text-white" />
                       </div>
                       <div>
                          <h4 className="text-xl font-black uppercase italic tracking-tighter">AI Mood Scout</h4>
                          <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Discover by Vibe</p>
                       </div>
                    </div>
                    <div className="h-px w-full md:w-px md:h-12 bg-white/10"></div>
                    <div className="flex flex-wrap gap-3">
                       {MOODS.map((mood) => (
                         <button
                           key={mood.label}
                           onClick={() => { setActiveMood(mood.label); setSearchQuery(mood.label); fetchSearch(mood.query); }}
                           className="px-6 py-2.5 bg-white/5 hover:bg-blue-600 text-white border border-white/10 hover:border-blue-500 rounded-full text-[10px] font-black uppercase tracking-widest transition-all active:scale-95 shadow-md"
                         >
                           {mood.label}
                         </button>
                       ))}
                    </div>
                 </div>
              </div>

              {moviesData.trending && (
                <MovieRow title={Category.TRENDING} movies={moviesData.trending} onPlay={handleOpenDetails} />
              )}

              {moviesData.originals && (
                <MovieRow title={Category.ORIGINALS} movies={moviesData.originals} onPlay={handleOpenDetails} />
              )}

              <div className="px-6 lg:px-12 my-32">
                <div className="relative h-[65vh] rounded-[3rem] overflow-hidden group shadow-2xl border border-white/5">
                  <div 
                    className="absolute inset-0 bg-cover bg-center transition-transform duration-[2000ms] group-hover:scale-110"
                    style={{ backgroundImage: `url(${(moviesData.topRated?.[0] || FALLBACK_MOVIE).heroImage})` }}
                  />
                  <div className="absolute inset-0 bg-gradient-to-r from-black via-black/70 to-transparent p-16 flex flex-col justify-center max-w-2xl">
                    <div className="flex items-center gap-4 mb-6">
                      <div className="bg-blue-600 p-2 rounded-lg">
                        <Flame className="w-5 h-5 text-white fill-current" />
                      </div>
                      <span className="text-blue-400 font-black tracking-[0.5em] text-[10px] uppercase">Cinema Hall of Fame</span>
                    </div>
                    <h2 className="text-6xl md:text-8xl font-black mb-8 uppercase tracking-tighter leading-none italic">
                      {(moviesData.topRated?.[0] || FALLBACK_MOVIE).title}
                    </h2>
                    <div className="flex gap-6">
                      <button 
                        onClick={() => handleOpenDetails(moviesData.topRated?.[0] || FALLBACK_MOVIE)}
                        className="bg-blue-600 hover:bg-blue-500 text-white px-12 py-5 rounded-full font-black uppercase tracking-widest text-[11px] transition-all transform hover:scale-105 active:scale-95 shadow-2xl"
                      >
                        Explore Entry
                      </button>
                    </div>
                  </div>
                </div>
              </div>

              {moviesData.actionMovies && (
                <MovieRow title={Category.ACTION} movies={moviesData.actionMovies} onPlay={handleOpenDetails} />
              )}
            </div>
          </>
        )}
      </main>

      <Footer />

      {isPlaying && selectedMovie && (
        <VideoPlayer 
          movie={selectedMovie} 
          onClose={() => setIsPlaying(false)} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, Star, Globe, Calendar, MapPin, User, Film } from 'lucide-react';
import { Person, Movie } from '../types';
import { TMDB_BASE_URL, TMDB_API_KEY, TMDB_IMAGE_BASE_URL } from '../constants';

interface PersonDetailsPageProps {
  person: Person;
  onBack: () => void;
  onMovieClick: (movie: Movie) => void;
}

interface PersonExtended {
  biography: string;
  birthday: string | null;
  place_of_birth: string | null;
  known_for_department: string;
  profile_path: string | null;
  credits: Movie[];
}

const PersonDetailsPage: React.FC<PersonDetailsPageProps> = ({ person, onBack, onMovieClick }) => {
  const [details, setDetails] = useState<PersonExtended | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchPersonData = async () => {
      setLoading(true);
      try {
        const [bioRes, creditsRes] = await Promise.all([
          fetch(`${TMDB_BASE_URL}/person/${person.id}?api_key=${TMDB_API_KEY}&language=en-US`),
          fetch(`${TMDB_BASE_URL}/person/${person.id}/combined_credits?api_key=${TMDB_API_KEY}&language=en-US`)
        ]);

        const bioData = await bioRes.json();
        const creditsData = await creditsRes.json();

        // Sort credits by popularity and filter to top 12
        const topCredits = creditsData.cast
          .sort((a: any, b: any) => b.popularity - a.popularity)
          .slice(0, 12)
          .map((item: any) => ({
            id: item.id.toString(),
            title: item.title || item.name || 'Untitled',
            description: item.overview || '',
            thumbnail: item.poster_path ? `${TMDB_IMAGE_BASE_URL}/w500${item.poster_path}` : '',
            heroImage: item.backdrop_path ? `${TMDB_IMAGE_BASE_URL}/original${item.backdrop_path}` : '',
            year: (item.release_date || item.first_air_date || '').split('-')[0] || '----',
            rating: (item.vote_average || 0).toFixed(1),
            duration: item.media_type === 'tv' ? 'Series' : 'Feature',
            category: 'Credit',
            tags: []
          }));

        setDetails({
          biography: bioData.biography || 'No biography available in the CineBlaze database.',
          birthday: bioData.birthday,
          place_of_birth: bioData.place_of_birth,
          known_for_department: bioData.known_for_department,
          profile_path: bioData.profile_path,
          credits: topCredits
        });
      } catch (error) {
        console.error("Error fetching person details:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchPersonData();
  }, [person]);

  if (loading) {
    return (
      <div className="min-h-screen bg-[#030303] flex items-center justify-center">
        <div className="flex flex-col items-center gap-4 animate-pulse">
          <div className="w-16 h-16 rounded-full border-4 border-blue-600 border-t-transparent animate-spin" />
          <span className="text-[10px] font-black uppercase tracking-widest text-gray-500">Accessing Talent Records...</span>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#030303] animate-in fade-in duration-700">
      {/* Background Ambience */}
      <div className="fixed inset-0 pointer-events-none opacity-20 overflow-hidden">
        <div className="absolute top-0 right-0 w-[50vw] h-[50vh] bg-blue-600/20 blur-[150px] rounded-full -translate-y-1/2 translate-x-1/2" />
        <div className="absolute bottom-0 left-0 w-[40vw] h-[40vh] bg-blue-900/10 blur-[150px] rounded-full translate-y-1/2 -translate-x-1/2" />
      </div>

      <div className="max-w-7xl mx-auto px-6 lg:px-12 pt-32 pb-24 relative z-10">
        <button 
          onClick={onBack}
          className="mb-12 flex items-center gap-3 px-6 py-2.5 bg-white/5 hover:bg-blue-600 border border-white/10 rounded-full text-[10px] font-black uppercase tracking-widest transition-all group"
        >
          <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
          Back to Database
        </button>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-16">
          {/* Sidebar: Profile Photo & Key Info */}
          <div className="lg:col-span-4 space-y-10">
            <div className="rounded-[3rem] overflow-hidden shadow-[0_40px_100px_rgba(0,0,0,0.8)] border border-white/10 group">
              <img 
                src={details?.profile_path ? `${TMDB_IMAGE_BASE_URL}/h632${details.profile_path}` : 'https://via.placeholder.com/632x948?text=No+Photo'} 
                alt={person.name} 
                className="w-full object-cover group-hover:scale-110 transition-transform duration-[2000ms]" 
              />
            </div>

            <div className="bg-white/5 border border-white/10 rounded-[2rem] p-8 space-y-6 backdrop-blur-xl">
              <h4 className="text-[10px] font-black uppercase tracking-[0.4em] text-blue-500 border-b border-white/5 pb-4">Personal Records</h4>

              <div className="space-y-4">
                <div className="flex items-center gap-4">
                  <User className="w-4 h-4 text-gray-500" />
                  <div>
                    <p className="text-[9px] font-black text-gray-600 uppercase tracking-widest">Department</p>
                    <p className="text-sm font-bold">{details?.known_for_department}</p>
                  </div>
                </div>

                <div className="flex items-center gap-4">
                  <Calendar className="w-4 h-4 text-gray-500" />
                  <div>
                    <p className="text-[9px] font-black text-gray-600 uppercase tracking-widest">Born</p>
                    <p className="text-sm font-bold">{details?.birthday || 'Unknown'}</p>
                  </div>
                </div>

                <div className="flex items-center gap-4">
                  <MapPin className="w-4 h-4 text-gray-500" />
