            <div className="space-y-10">
              <div className="flex items-center justify-between border-b border-white/5 pb-6">
                <div className="flex items-center gap-3">
                  <Film className="w-5 h-5 text-blue-500" />
                  <h3 className="text-xl font-black uppercase italic">Known For</h3>
                </div>
                <span className="text-[10px] font-black uppercase tracking-widest text-gray-600">Featured Credits</span>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-6">
                {details?.credits.map((movie) => (
                  <div 
                    key={movie.id} 
                    onClick={() => onMovieClick(movie)}
                    className="group cursor-pointer space-y-4"
                  >
                    <div className="aspect-[2/3] rounded-2xl overflow-hidden border border-white/5 group-hover:border-blue-500/50 transition-all shadow-xl">
                      <img 
